window.JOURNAL_MINDMAPS=[{"title":"数学 01 · 函数、极限与连续","children":[{"title":"1.1 函数","children":[{"title":"函数的定义域、对应法则和值域","children":[{"title":"定义域与对应法则确定函数，值域由二者共同决定。同一函数须定义域和对应法则均相同。","children":[],"note":""},{"title":"分母≠0，偶次根式内部≥0，对数真数>0。根式作分母时被开方数>0。","children":[],"note":""},{"title":"求解析式看给定形式：代入、换元、联立。分段函数先按自变量所在区间选式。","children":[],"note":""}],"note":""},{"title":"函数性质与基本图像","children":[{"title":"奇偶性先检查定义域关于原点对称，再比 f(−x) 与 ±f(x)。","children":[],"note":""},{"title":"单调性写明区间；周期需对允许的 x 满足 f(x+T)=f(x)；有界要区分上界、下界。","children":[],"note":""},{"title":"熟悉幂、指数、对数、三角和反三角图像。平移、伸缩、对称后复查定义域。","children":[],"note":""}],"note":""},{"title":"复合函数与反函数","children":[{"title":"复合 f(g(x))：x∈Dg 且 g(x)∈Df。","children":[],"note":""},{"title":"求反函数先确定一一对应的区间，再交换自、因变量并解出 y。","children":[],"note":""},{"title":"原函数定义域与值域互换，图像关于 y=x 对称。","children":[],"note":""}],"note":""},{"title":"函数相同的判定","children":[{"title":"判断两个函数是否相同，必须同时满足定义域相同和对应法则相同。","children":[],"note":""},{"title":"判断顺序：先比较定义域，再在各自定义域内化简并比较对应法则。","children":[],"note":""}],"note":""},{"title":"函数定义域的常见限制","children":[{"title":"分式函数：分母不能为0。","children":[],"note":""},{"title":"偶次根式：被开方数必须大于或等于0。","children":[],"note":""},{"title":"对数函数：真数必须大于0；若对数在分母，还要保证对数值不为0。","children":[],"note":""},{"title":"tan x要求x≠kπ+π/2；cot x要求x≠kπ。","children":[],"note":""},{"title":"arcsin x和arccos x的自变量必须属于[−1,1]。","children":[],"note":""}],"note":""},{"title":"抽象函数定义域：同位置，范围同","children":[{"title":"若f(x)的定义域为[a,b]，则f[g(x)]有意义必须满足a≤g(x)≤b。","children":[],"note":""},{"title":"若已知f[g(x)]的定义域，先求出g(x)在该定义域上的取值范围，再把它作为f的定义域。","children":[],"note":""},{"title":"不同复合形式之间转换时，先还原f的自变量范围，再代入新的内层表达式。","children":[],"note":""}],"note":""},{"title":"常见函数定义域","children":[{"title":"分式函数 y=1/x 的定义域要求 x≠0。","children":[],"note":""},{"title":"偶次根式 y=\\(\\sqrt[2n]{x}\\) 的定义域要求 x≥0。","children":[],"note":""},{"title":"奇次根式 y=\\(\\sqrt[2n+1]{x}\\) 的定义域为全体实数 R。","children":[],"note":""},{"title":"对数函数 y=logₐx 的定义域要求 x>0。","children":[],"note":""},{"title":"正切函数 y=tan x 的定义域要求 x≠π/2+kπ（k∈Z）。","children":[],"note":""},{"title":"余切函数 y=cot x 的定义域要求 x≠kπ（k∈Z）。","children":[],"note":""},{"title":"反正弦函数 y=arcsin x 和反余弦函数 y=arccos x 的定义域都是 [−1,1]。","children":[],"note":""}],"note":""},{"title":"抽象函数定义域同位置法","children":[{"title":"若f(A)与f(B)中的函数符号相同，则A和B的取值范围相同。","children":[],"note":""},{"title":"先求已知括号内整体的范围，再令新括号内整体落入该范围。","children":[],"note":""}],"note":""},{"title":"函数概念与两大要素","children":[{"title":"在某个变化过程中有两个变量x和y，当x在给定范围内取每一个值时，y都有唯一确定的值与它对应，称y是x的函数，记作y=f(x)。","children":[],"note":""},{"title":"x是自变量，y是因变量；自变量可取值的集合是定义域。","children":[],"note":""},{"title":"函数的两大要素是定义域和对应法则。","children":[],"note":""},{"title":"值域不是独立给出的第三个要素，而是由定义域和对应法则共同确定。","children":[],"note":""},{"title":"看一个关系是否构成函数，关键是定义域中的每个x是否只有一个y与之对应。","children":[],"note":""},{"title":"一个y可以对应多个x，但一个x不能同时对应多个y。","children":[],"note":""},{"title":"判断函数相同：定义域相同 + 对应法则相同。","children":[],"note":""},{"title":"定义域：函数有意义时自变量x允许取值的集合；值域：函数值y=f(x)实际取得的集合。","children":[],"note":""},{"title":"定义域优先检查分母≠0、偶次根式被开方数≥0、对数真数>0且底数>0且底数≠1。","children":[],"note":""},{"title":"复合函数f(g(x))的定义域必须同时满足x∈Dg且g(x)∈Df；求交集后再写成区间或集合。","children":[],"note":""},{"title":"同一函数的判定要同时看定义域和对应关系；只看解析式相同或只看图像形状都不充分。","children":[],"note":""}],"note":""},{"title":"定义域解题流程与易错点","children":[{"title":"第一步：根据分母、根式、对数、反三角函数等逐项列限制。","children":[],"note":""},{"title":"第二步：分别解出每个限制对应的区间。","children":[],"note":""},{"title":"第三步：所有限制同时满足，取交集并用区间表示。","children":[],"note":""},{"title":"分段函数的定义域按题目给出的各段区间取并集。","children":[],"note":""},{"title":"端点是否包含由≤、≥、<、>以及表达式是否有意义共同决定。","children":[],"note":""},{"title":"对数在分母时，不能只写真数>0，还要排除对数值为0的点。","children":[],"note":""},{"title":"化简后的表达式不能替代原式定义域；被约掉的点仍然必须排除。","children":[],"note":""},{"title":"周期函数限制与有限区间结合时，只保留落在目标区间内的周期点。","children":[],"note":""},{"title":"检查答案：区间端点、被排除点、并集符号是否写完整。","children":[],"note":""}],"note":""},{"title":"具体函数定义域进阶","children":[{"title":"第一步：对根式、对数、分母、反三角函数等每一项分别列出有意义条件。","children":[],"note":""},{"title":"第二步：分别解出各条件对应的区间。","children":[],"note":""},{"title":"第三步：把所有条件取交集，并检查端点是否能取。","children":[],"note":""},{"title":"偶次根被开方数≥0；对数真数>0；arcsin与arccos的自变量必须在[-1,1]。","children":[],"note":""},{"title":"涉及sin x>0等周期条件时，可以画简图，再与有限区间求交集。","children":[],"note":""},{"title":"分段函数的定义域由各段给定区间决定，最后取并集；同一点是否包含要看至少有一段是否包含该点。","children":[],"note":""},{"title":"交集处理“同时满足”，并集处理“任一分段覆盖”。","children":[],"note":""}],"note":""},{"title":"抽象函数定义域转换","children":[{"title":"把g(x)放到原来x的位置，要求g(x)落入f(x)的定义域。","children":[],"note":""},{"title":"例如f(x)定义域为[3,5]，则f(2x+1)要求3≤2x+1≤5。","children":[],"note":""},{"title":"最终答案是外层x的范围。","children":[],"note":""},{"title":"给出的定义域限制的是复合函数外层x。","children":[],"note":""},{"title":"把外层x在给定区间内代入g(x)，求出g(x)的值域，该值域就是f的定义域。","children":[],"note":""},{"title":"例如f(2x+1)在[3,5]有定义，则f的定义域为[7,11]。","children":[],"note":""},{"title":"先还原f的定义域，再让新的内层表达式落入该范围。","children":[],"note":""},{"title":"不能跳过“还原f定义域”这一步。","children":[],"note":""},{"title":"同位置，范围同。","children":[],"note":""}],"note":""},{"title":"奇偶性1——奇偶性定义","children":[{"title":"判断函数奇偶性的前提是定义域关于原点对称。","children":[],"note":""},{"title":"若f(-x)=-f(x)，函数为奇函数，图像关于原点对称。","children":[],"note":""},{"title":"若f(-x)=f(x)，函数为偶函数，图像关于y轴对称。","children":[],"note":""},{"title":"若奇函数在x=0处有定义，则其图像经过(0,0)。","children":[],"note":""}],"note":""},{"title":"奇偶性2——常见奇函数","children":[{"title":"常见奇函数：sin x、tan x、cot x。","children":[],"note":""},{"title":"常见奇函数：arcsin x、arctan x。","children":[],"note":""},{"title":"奇次幂函数x^(2n+1)是奇函数。","children":[],"note":""}],"note":""},{"title":"奇偶性3——常见偶函数","children":[{"title":"cos x是偶函数。","children":[],"note":""},{"title":"|x|是偶函数。","children":[],"note":""},{"title":"偶次幂函数x^(2n)是偶函数。","children":[],"note":""},{"title":"定义域关于原点对称的常数函数是偶函数。","children":[],"note":""}],"note":""},{"title":"有界——常见有界函数","children":[{"title":"sin x和cos x是有界函数。","children":[],"note":""},{"title":"arcsin x、arccos x、arctan x、arccot x是有界函数。","children":[],"note":""}],"note":""},{"title":"函数的性质","children":[{"title":"求函数解析式可使用换元法。","children":[],"note":""},{"title":"判断奇偶性前先检查定义域是否关于原点对称。","children":[],"note":""}],"note":""},{"title":"奇偶性定义与判断前提","children":[{"title":"判断奇偶性前，定义域必须关于原点对称。","children":[],"note":""},{"title":"f(-x)=f(x)是偶函数，图像关于y轴对称。","children":[],"note":""},{"title":"f(-x)=-f(x)是奇函数，图像关于原点对称。","children":[],"note":""},{"title":"若奇函数在x=0处有定义，则f(0)=0。","children":[],"note":""}],"note":""},{"title":"常见奇偶函数与运算规律","children":[{"title":"常见奇函数：sin x、tan x、cot x、arcsin x、arctan x、x^(2n+1)。","children":[],"note":""},{"title":"常见偶函数：cos x、|x|、x^(2n)、常数函数。","children":[],"note":""},{"title":"奇±奇仍为奇，偶±偶仍为偶；奇×奇为偶，偶×偶为偶，奇×偶为奇。","children":[],"note":""}],"note":""},{"title":"单调性与周期性","children":[{"title":"若x₁<x₂时f(x₁)<f(x₂)，函数在区间上单调递增。","children":[],"note":""},{"title":"若x₁<x₂时f(x₁)>f(x₂)，函数在区间上单调递减。","children":[],"note":""},{"title":"若存在非零常数T使f(x+T)=f(x)，则T是周期；最小正T称最小正周期。","children":[],"note":""}],"note":""},{"title":"函数有界性的判定","children":[{"title":"存在正数M使对所有x∈D有|f(x)|≤M，则函数在D上有界。","children":[],"note":""},{"title":"有界等价于同时存在上界和下界。","children":[],"note":""},{"title":"sin、cos及反三角函数在各自定义域上有界；arctan、arccot也有界。","children":[],"note":""}],"note":""},{"title":"换元与奇偶性综合方法","children":[{"title":"判断奇偶性必须同时检查定义域对称和f(-x)关系。","children":[],"note":""},{"title":"分段函数求f(-x)时要根据-x落入的区间选择对应表达式。","children":[],"note":""}],"note":""},{"title":"函数图像1——幂函数","children":[{"title":"幂函数y=x^α在有定义时经过(1,1)。","children":[],"note":""},{"title":"α>1时第一象限内递增且上凸；0<α<1时递增且下凹。","children":[],"note":""},{"title":"α<0时在x>0上递减，x=0为竖直渐近线。","children":[],"note":""}],"note":""},{"title":"函数图像2——指数函数","children":[{"title":"指数函数定义域为R，值域为(0,+∞)。","children":[],"note":""},{"title":"图像经过(0,1)。","children":[],"note":""},{"title":"a>1时递增；0<a<1时递减。","children":[],"note":""},{"title":"y=0是水平渐近线。","children":[],"note":""}],"note":""},{"title":"函数图像3——对数函数","children":[{"title":"对数函数定义域为(0,+∞)，值域为R。","children":[],"note":""},{"title":"图像经过(1,0)。","children":[],"note":""},{"title":"x=0是竖直渐近线。","children":[],"note":""}],"note":""},{"title":"函数图像4——三角函数","children":[{"title":"sin x为奇函数，cos x为偶函数，二者周期均为2π，值域均为[-1,1]。","children":[],"note":""},{"title":"tan x为奇函数，周期为π，在x=π/2+kπ处无定义。","children":[],"note":""}],"note":""},{"title":"函数图像5——反三角函数","children":[{"title":"arcsin x定义域[-1,1]，值域[-π/2,π/2]，单调递增。","children":[],"note":""},{"title":"arccos x定义域[-1,1]，值域[0,π]，单调递减。","children":[],"note":""},{"title":"arctan x定义域R，值域(-π/2,π/2)，单调递增。","children":[],"note":""}],"note":""},{"title":"幂函数运算规律","children":[{"title":"a^m·a^n=a^(m+n)。","children":[],"note":""},{"title":"a^m/a^n=a^(m-n)（a≠0）。","children":[],"note":""},{"title":"(a^m)^n=a^(mn)。","children":[],"note":""},{"title":"a^(-n)=1/a^n。","children":[],"note":""},{"title":"a^(m/n)=n次根号下a^m。","children":[],"note":""}],"note":""},{"title":"平方与立方公式","children":[{"title":"(a+b)^2=a^2+2ab+b^2。","children":[],"note":""},{"title":"(a-b)^2=a^2-2ab+b^2。","children":[],"note":""},{"title":"a^2-b^2=(a+b)(a-b)。","children":[],"note":""},{"title":"a^3-b^3=(a-b)(a^2+ab+b^2)。","children":[],"note":""},{"title":"a^3+b^3=(a+b)(a^2-ab+b^2)。","children":[],"note":""}],"note":""},{"title":"一元二次方程求根公式","children":[{"title":"一元二次方程一般式为ax²+bx+c=0（a≠0）。","children":[],"note":""},{"title":"求根公式x=(-b±√Δ)/(2a)。","children":[],"note":""},{"title":"判别式Δ=b²-4ac。","children":[],"note":""},{"title":"Δ>0有两个不等实根；Δ=0有两个相等实根；Δ<0无实根。","children":[],"note":""}],"note":""},{"title":"一元二次方程与复数","children":[{"title":"虚数单位i满足i²=-1。","children":[],"note":""},{"title":"当Δ<0时，一元二次方程在复数范围内有一对共轭复根。","children":[],"note":""},{"title":"复数乘法按多项式展开并用i²=-1化简。","children":[],"note":""}],"note":""},{"title":"指数运算规律","children":[{"title":"a^m/a^n=a^(m-n)。","children":[],"note":""},{"title":"(ab)^n=a^n b^n。","children":[],"note":""}],"note":""},{"title":"对数运算性质","children":[{"title":"log_a1=0。","children":[],"note":""},{"title":"log_aa=1。","children":[],"note":""},{"title":"log_a(mn)=log_am+log_an。","children":[],"note":""},{"title":"log_a(m/n)=log_am-log_an。","children":[],"note":""},{"title":"log_a(m^n)=nlog_am。","children":[],"note":""},{"title":"a^(log_aN)=N。","children":[],"note":""}],"note":""},{"title":"三角函数定义","children":[{"title":"sinα=对边/斜边。","children":[],"note":""},{"title":"cosα=邻边/斜边。","children":[],"note":""},{"title":"tanα=对边/邻边。","children":[],"note":""},{"title":"cotα=邻边/对边。","children":[],"note":""},{"title":"secα=斜边/邻边。","children":[],"note":""},{"title":"cscα=斜边/对边。","children":[],"note":""}],"note":""},{"title":"三角函数倒数关系","children":[{"title":"1/sin x=csc x。","children":[],"note":""},{"title":"1/cos x=sec x。","children":[],"note":""},{"title":"1/tan x=cot x=cos x/sin x。","children":[],"note":""}],"note":""},{"title":"三角函数平方关系","children":[{"title":"sin²x+cos²x=1。","children":[],"note":""},{"title":"tan²x+1=sec²x。","children":[],"note":""},{"title":"cot²x+1=csc²x。","children":[],"note":""}],"note":""},{"title":"二倍角公式","children":[{"title":"sin2x=2sinx cosx。","children":[],"note":""},{"title":"cos2x=cos²x-sin²x。","children":[],"note":""},{"title":"cos2x=2cos²x-1。","children":[],"note":""},{"title":"cos2x=1-2sin²x。","children":[],"note":""}],"note":""},{"title":"降幂公式","children":[{"title":"sin²x=(1-cos2x)/2。","children":[],"note":""},{"title":"cos²x=(1+cos2x)/2。","children":[],"note":""}],"note":""},{"title":"特殊角三角函数值","children":[{"title":"sin0=0，cos0=1。","children":[],"note":""},{"title":"sin(π/6)=1/2，cos(π/6)=√3/2。","children":[],"note":""},{"title":"sin(π/4)=cos(π/4)=√2/2。","children":[],"note":""},{"title":"sin(π/3)=√3/2，cos(π/3)=1/2。","children":[],"note":""},{"title":"sin(π/2)=1，cos(π/2)=0。","children":[],"note":""}],"note":""},{"title":"各大类函数分类与反函数","children":[{"title":"求反函数必须先解出x，再交换x、y，并写出反函数定义域。","children":[],"note":""}],"note":""},{"title":"反函数定义、存在条件与求解步骤","children":[{"title":"函数在给定定义域上必须一一对应才有反函数。","children":[],"note":""},{"title":"求反函数：由y=f(x)反解x；交换x、y；写出反函数定义域。","children":[],"note":""},{"title":"反函数定义域等于原函数值域，反函数值域等于原函数定义域。","children":[],"note":""}],"note":""},{"title":"反函数性质与常见互反函数","children":[{"title":"原函数与反函数单调性相同。","children":[],"note":""},{"title":"原函数定义域与反函数值域互换，原函数值域与反函数定义域互换。","children":[],"note":""},{"title":"两者图像关于直线y=x对称。","children":[],"note":""},{"title":"指数函数与对数函数互为反函数；限定区间上的三角函数与反三角函数互为反函数。","children":[],"note":""}],"note":""},{"title":"反函数典型结构与定义域回填","children":[{"title":"求反函数不仅要交换x、y，还要确定原函数值域。","children":[],"note":""},{"title":"根式函数反解后要保留非负限制。","children":[],"note":""},{"title":"分式指数函数可先令t=a^x，再解有理方程。","children":[],"note":""},{"title":"三角函数必须在指定单调区间上反解。","children":[],"note":""}],"note":""},{"title":"求解步骤——反函数","children":[{"title":"反函数把原函数的“输入—输出”关系反过来，所以交换变量后，原函数值域成为反函数定义域。","children":[],"note":""},{"title":"原函数必须在所讨论区间上具有一一对应关系，才能存在反函数。","children":[],"note":""},{"title":"第一步：从y=f(x)中反解出x=f⁻¹(y)。","children":[],"note":""},{"title":"第二步：交换变量x、y，得到y=f⁻¹(x)。","children":[],"note":""},{"title":"第三步：求反函数定义域，它等于原函数的值域。","children":[],"note":""},{"title":"先写y=f(x)，交换x、y，再解出y=f⁻¹(x)。","children":[],"note":""},{"title":"原函数必须在所取定义域上单调，才有反函数；原函数值域成为反函数定义域。","children":[],"note":""},{"title":"验证：f⁻¹(f(x))=x（x在原定义域内），f(f⁻¹(x))=x（x在原值域内）。","children":[],"note":""},{"title":"互为反函数图像关于直线y=x对称；定义域和值域互换。","children":[],"note":""}],"note":""},{"title":"求函数解析式——代入法","children":[{"title":"已知f(x)解析式，求f(φ(x))时把解析式中的x整体替换为φ(x)。","children":[],"note":""},{"title":"多重复合按从里到外逐层代入。","children":[],"note":""}],"note":""},{"title":"求函数解析式——换元与配凑法","children":[{"title":"令φ(x)=t，并把右侧表达式全部改写成t。","children":[],"note":""},{"title":"若能反解x，用x关于t的表达式代回；不能直接反解时可利用恒等式配凑。","children":[],"note":""}],"note":""},{"title":"幂、指数、对数函数性质","children":[{"title":"指数函数y=a^x满足a>0且a≠1，定义域R，值域(0,+∞)，过(0,1)。","children":[],"note":""},{"title":"对数函数y=logₐx满足a>0且a≠1，定义域(0,+∞)，值域R，过(1,0)。","children":[],"note":""},{"title":"a>1时指数和对数函数递增，0<a<1时递减。","children":[],"note":""},{"title":"指数函数与对数函数图像关于y=x对称。","children":[],"note":""}],"note":""},{"title":"三角函数图像性质与常用公式","children":[{"title":"sin x是奇函数，cos x是偶函数，二者周期2π且有界。","children":[],"note":""},{"title":"tan x和cot x是奇函数，周期π，在各自定义区间单调。","children":[],"note":""},{"title":"sin2x=2sinx cosx，cos2x=cos²x-sin²x。","children":[],"note":""}],"note":""},{"title":"反三角函数图像与性质","children":[{"title":"arcsin x定义域[-1,1]，值域[-π/2,π/2]，递增且为奇函数。","children":[],"note":""},{"title":"arccos x定义域[-1,1]，值域[0,π]，递减且非奇非偶。","children":[],"note":""},{"title":"arctan x定义域R，值域(-π/2,π/2)，递增且为奇函数。","children":[],"note":""},{"title":"arccot x定义域R，值域(0,π)，递减且非奇非偶。","children":[],"note":""}],"note":""},{"title":"复合、基本初等、初等与分段函数","children":[{"title":"y=f(φ(x))中φ是内函数，f是外函数。","children":[],"note":""},{"title":"复合函数分解遵循从外向内逐层拆分。","children":[],"note":""},{"title":"基本初等函数经有限次四则运算或有限次复合形成初等函数。","children":[],"note":""},{"title":"分段函数在不同定义域区间采用不同对应法则。","children":[],"note":""}],"note":""}],"note":""},{"title":"1.2 极限","children":[{"title":"极限概念与性质","children":[{"title":"分清数列极限、函数极限、左极限和右极限。两侧有限极限相等才有两侧极限。","children":[],"note":""},{"title":"极限存在并不要求该点有定义。四则运算时，商的分母极限不能为 0。","children":[],"note":""},{"title":"夹逼准则、单调有界准则、无穷小与无穷大。无穷小是过程中的趋近量。","children":[],"note":""}],"note":""},{"title":"极限计算","children":[{"title":"能代入先代入；0/0 先想因式分解、约分、有理化、等价无穷小。","children":[],"note":""},{"title":"x→0：sin x∼x，tan x∼x，ln(1+x)∼x，eˣ−1∼x，1−cos x∼x²/2。","children":[],"note":""},{"title":"两个重要极限：\\(\\lim_{x\\to0}\\frac{\\sin x}{x}=1\\)；\\(\\lim_{x\\to+\\infty}\\left(1+\\frac1x\\right)^x=e\\)。等价替换优先用于乘除，和差需防消项。","children":[],"note":""}],"note":""},{"title":"反三角函数、函数分类与极限概念","children":[{"title":"数列极限研究n→∞时数列项的变化。","children":[],"note":""},{"title":"函数极限研究x趋近某点或无穷时函数值的变化。","children":[],"note":""}],"note":""},{"title":"数列极限与函数极限入门","children":[{"title":"数列1/n在n→∞时极限为0。","children":[],"note":""},{"title":"数列2^n在n→∞时趋于+∞。","children":[],"note":""},{"title":"sin n一般无极限，因为持续振荡。","children":[],"note":""},{"title":"求x→∞函数极限要分析主导项或函数图像的水平趋势。","children":[],"note":""}],"note":""}],"note":""},{"title":"1.3 连续与间断","children":[{"title":"连续性与间断点","children":[{"title":"点连续：f(a) 有定义、lim f(x) 存在且等于 f(a)。分段点分别求左右极限再比点值。","children":[],"note":""},{"title":"第一类：可去、跳跃。第二类：无穷、振荡等至少一侧有限极限不存在。","children":[],"note":""},{"title":"闭区间连续可用最值定理与介值定理；异号端点保证区间内存在零点。","children":[],"note":""}],"note":""},{"title":"连续的闭区间性质","children":[{"title":"最值定理要求在闭区间上连续。","children":[],"note":""},{"title":"介值定理给出两函数值之间每个值的存在性。","children":[],"note":""},{"title":"证明不动点时可设 F(x)=f(x)−x，再检查端点异号或为零。","children":[],"note":""}],"note":""}],"note":""}],"note":"定义域先行 → 选极限方法 → 回到点值判断连续"},{"title":"数学 02 · 导数与微分","children":[{"title":"2.1 导数","children":[{"title":"导数定义与几何意义","children":[{"title":"导数是差商在增量趋零时的有限极限，切线斜率为 f′(a)。","children":[],"note":""},{"title":"分段点用定义求左右导数，二者存在且相等才可导。可导必连续。","children":[],"note":""},{"title":"切线 y−f(a)=f′(a)(x−a)。斜率非零时法线斜率为 −1/f′(a)。","children":[],"note":""}],"note":""},{"title":"求导方法","children":[{"title":"基本函数公式 → 和差积商 → 复合函数链式法则，记得乘内层导数。","children":[],"note":""},{"title":"隐函数：两边对 x 求导；参数方程：\\(\\frac{\\mathrm dy}{\\mathrm dx}=\\frac{\\mathrm dy/\\mathrm dt}{\\mathrm dx/\\mathrm dt}\\)，要求 dx/dt≠0。","children":[],"note":""},{"title":"幂指函数可对数求导；高阶导数逐次求，参数式再次对 x 求导时仍需除以 dx/dt。","children":[],"note":""}],"note":""},{"title":"微分与近似","children":[{"title":"dy=f′(x) dx。Δy=f′(x)Δx+o(Δx)。","children":[],"note":""},{"title":"当 Δx 很小时，用 f(x+Δx)≈f(x)+f′(x)Δx。","children":[],"note":""},{"title":"用微分估算时先选容易代入的基点，保留变化量的正负号。","children":[],"note":""}],"note":""},{"title":"基本求导公式","children":[{"title":"(xⁿ)′=nxⁿ⁻¹。","children":[],"note":""},{"title":"(sin x)′=cos x，(cos x)′=−sin x。","children":[],"note":""},{"title":"(ln x)′=1/x（x>0），(eˣ)′=eˣ。","children":[],"note":""},{"title":"(uv)′=u′v+uv′，(u/v)′=(u′v−uv′)/v²。","children":[],"note":""}],"note":""},{"title":"导数","children":[{"title":"极限定义求导","children":[],"note":""},{"title":"按定义求导","children":[],"note":""},{"title":"分段函数可导性","children":[],"note":""},{"title":"绝对值函数可导性","children":[],"note":""},{"title":"切线与法线方程","children":[],"note":""},{"title":"由切线求切点","children":[],"note":""},{"title":"过外点作曲线切线","children":[],"note":""},{"title":"连续与可导关系","children":[],"note":""},{"title":"分段函数可导参数","children":[],"note":""},{"title":"正切函数求导","children":[],"note":""},{"title":"余割函数求导","children":[],"note":""},{"title":"基本初等函数求导","children":[],"note":""},{"title":"乘积函数求导","children":[],"note":""},{"title":"点处导数","children":[],"note":""},{"title":"商函数求导","children":[],"note":""},{"title":"反三角函数求导","children":[],"note":""},{"title":"反函数的导数","children":[],"note":""},{"title":"复合函数求导","children":[],"note":""},{"title":"多层复合函数求导","children":[],"note":""},{"title":"多层对数求导","children":[],"note":""},{"title":"反三角复合函数求导","children":[],"note":""},{"title":"对数根式函数求导","children":[],"note":""},{"title":"抽象复合函数求导","children":[],"note":""},{"title":"抽象函数与根式求导","children":[],"note":""},{"title":"隐函数求导","children":[],"note":""},{"title":"隐函数切线","children":[],"note":""},{"title":"参数方程求导","children":[],"note":""},{"title":"参数方程点值导数","children":[],"note":""},{"title":"参数方程切线与法线","children":[],"note":""},{"title":"幂指函数求导","children":[],"note":""},{"title":"对数求导","children":[],"note":""},{"title":"多因子对数求导","children":[],"note":""},{"title":"二阶导数","children":[],"note":""},{"title":"四阶导数","children":[],"note":""},{"title":"n阶导数","children":[],"note":""},{"title":"函数微分","children":[],"note":""},{"title":"微分","children":[],"note":""},{"title":"点处微分","children":[],"note":""}],"note":""}],"note":""},{"title":"2.2 导数的应用","children":[{"title":"单调、极值与曲线","children":[{"title":"列出驻点、不可导点，用 f′ 符号划区间。f′=0 只是极值候选。","children":[],"note":""},{"title":"闭区间最值比较端点和内部候选点。应用题先建模、写可行范围。","children":[],"note":""},{"title":"用 f″ 判断凹凸；找拐点要确认凹凸改变。渐近线用对应的单侧或无穷远极限判定。","children":[],"note":""}],"note":""},{"title":"洛必达与未定式","children":[{"title":"先确认 0/0 或 ∞/∞，并检查可导、分母导数非零及导数比的极限等条件。","children":[],"note":""},{"title":"0·∞、∞−∞ 先变形为商；幂指型先取对数，再还原指数。","children":[],"note":""},{"title":"每用一次都要重新检查未定式。能约分、有理化或用重要极限时可优先简化。","children":[],"note":""},{"title":"洛必达 0/0 型","children":[],"note":""},{"title":"洛必达多项式型","children":[],"note":""},{"title":"洛必达三角型","children":[],"note":""},{"title":"∞−∞ 型转化","children":[],"note":""},{"title":"多次洛必达","children":[],"note":""},{"title":"非零因子直接代入","children":[],"note":""},{"title":"对数比值极限","children":[],"note":""},{"title":"∞/∞ 型洛必达","children":[],"note":""},{"title":"因式分解求极限","children":[],"note":""},{"title":"无理根式有理化","children":[],"note":""},{"title":"0·∞ 型","children":[],"note":""},{"title":"0·∞ 型指数","children":[],"note":""},{"title":"幂指函数 0^0 型","children":[],"note":""},{"title":"幂指函数 1^0 型","children":[],"note":""},{"title":"∞−∞ 根式型","children":[],"note":""},{"title":"∞−∞ 三角型","children":[],"note":""}],"note":""},{"title":"单调性","children":[{"title":"指数函数单调性","children":[],"note":""},{"title":"含对数函数单调性","children":[],"note":""}],"note":""},{"title":"极值","children":[{"title":"多项式极值","children":[],"note":""},{"title":"不可导点与极值","children":[],"note":""},{"title":"有理函数极值","children":[],"note":""},{"title":"二阶导判极值","children":[],"note":""}],"note":""},{"title":"最值","children":[{"title":"闭区间最值","children":[],"note":""},{"title":"已知最值求参数","children":[],"note":""},{"title":"最值应用题","children":[],"note":""}],"note":""},{"title":"单调性证明","children":[{"title":"单调性证不等式","children":[],"note":""},{"title":"单调性证幂不等式","children":[],"note":""},{"title":"单调性证三角不等式","children":[],"note":""},{"title":"最小值证明无实根","children":[],"note":""}],"note":""},{"title":"凹凸与拐点","children":[{"title":"凹凸性与拐点","children":[],"note":""},{"title":"含对数凹凸与拐点","children":[],"note":""},{"title":"极值条件求参并判凹凸","children":[],"note":""}],"note":""},{"title":"渐近线","children":[{"title":"求三类渐近线","children":[],"note":""},{"title":"水平渐近线填空","children":[],"note":""},{"title":"水平与垂直渐近线","children":[],"note":""}],"note":""},{"title":"函数作图","children":[{"title":"描绘函数图像","children":[],"note":""}],"note":""}],"note":""},{"title":"2.3 微分中值定理","children":[{"title":"微分中值定理","children":[{"title":"罗尔：闭区间连续、开区间可导、端点函数值相等。","children":[],"note":""},{"title":"拉格朗日：闭区间连续、开区间可导，存在 ξ 使 \\(f\\prime(\\xi)=\\frac{f(b)-f(a)}{b-a}\\)。","children":[],"note":""},{"title":"柯西：两函数满足相应条件。证明题常先构造辅助函数，再验证条件、写出结论。","children":[],"note":""}],"note":""},{"title":"证明题的辅助函数","children":[{"title":"证明存在一点导数为指定斜率，可减去端点连线后用罗尔定理。","children":[],"note":""},{"title":"柯西定理可写成 [f(b)−f(a)]g′(ξ)=[g(b)−g(a)]f′(ξ)。","children":[],"note":""},{"title":"若要写成商式，先检查相应分母非零。","children":[],"note":""}],"note":""},{"title":"罗尔定理","children":[{"title":"罗尔定理条件判断","children":[],"note":""},{"title":"罗尔构造辅助函数","children":[],"note":""},{"title":"多项式零点存在","children":[],"note":""},{"title":"零点定理与罗尔综合","children":[],"note":""}],"note":""},{"title":"拉格朗日中值定理","children":[{"title":"拉格朗日条件判断","children":[],"note":""},{"title":"对数不等式","children":[],"note":""},{"title":"幂函数不等式","children":[],"note":""},{"title":"ln(1+x) 不等式","children":[],"note":""}],"note":""},{"title":"泰勒与麦克劳林","children":[{"title":"e^x 的 n 阶麦克劳林展开","children":[],"note":""},{"title":"sin x 的4阶麦克劳林展开","children":[],"note":""}],"note":""}],"note":""}],"note":"认结构选求导法 → 用符号做应用 → 核对定理条件"},{"title":"数学 03 · 一元函数积分学","children":[{"title":"3.1 不定积分","children":[{"title":"不定积分的概念","children":[{"title":"F′(x)=f(x) 时，∫f(x)dx=F(x)+C。公式使用要注意适用区间。","children":[],"note":""},{"title":"基本积分表先抓幂函数、1/x、指数、三角及反三角对应式。","children":[],"note":""},{"title":"∫1/x dx=ln∣x∣+C。做完可反求导，核对常数、符号和系数。","children":[],"note":""}],"note":""},{"title":"换元积分","children":[{"title":"第一类换元：看到 f(g(x))g′(x)，将内层 g(x) 凑成微分。","children":[],"note":""},{"title":"第二类换元：遇含根式等结构可用三角代换等简化，同时记录取值范围。","children":[],"note":""},{"title":"不定积分最后换回原变量。定积分如果换了上下限，就用新变量直接算完。","children":[],"note":""}],"note":""},{"title":"分部积分与常见类型","children":[{"title":"∫u dv=uv−∫v du。选 u 时考虑求导能否降阶，选 dv 时考虑能否积分。","children":[],"note":""},{"title":"多项式乘指数或三角常用分部；对数、反三角常把其作为 u。","children":[],"note":""},{"title":"有理函数先判断是否要做多项式除法或部分分式；三角式常先用恒等式整理。","children":[],"note":""}],"note":""},{"title":"基本积分公式","children":[{"title":"\\(\\int x^\\alpha\\,\\mathrm dx=\\frac{x^{\\alpha+1}}{\\alpha+1}+C\\)（α≠−1，在适用区间内）。","children":[],"note":""},{"title":"∫eˣdx=eˣ+C，∫sin x dx=−cos x+C。","children":[],"note":""},{"title":"\\(\\int\\frac{\\mathrm dx}{1+x^2}=\\arctan x+C\\)。","children":[],"note":""},{"title":"\\(\\int\\frac{\\mathrm dx}{\\sqrt{1-x^2}}=\\arcsin x+C\\)（|x|<1）。","children":[],"note":""}],"note":""},{"title":"不定积分基础公式总表｜幂函数、指数、三角与反三角","children":[{"title":"∫k dx=kx+C；∫x^μ dx=x^(μ+1)/(μ+1)+C（μ≠−1）。","children":[],"note":""},{"title":"∫1/x dx=ln|x|+C；∫1/√x dx=2√x+C；∫1/x² dx=−1/x+C。","children":[],"note":""},{"title":"∫sin x dx=−cos x+C；∫cos x dx=sin x+C。","children":[],"note":""},{"title":"∫sec²x dx=tan x+C；∫csc²x dx=−cot x+C。","children":[],"note":""},{"title":"∫sec x tan x dx=sec x+C；∫csc x cot x dx=−csc x+C。","children":[],"note":""},{"title":"∫tan x dx=−ln|cos x|+C=ln|sec x|+C；∫cot x dx=ln|sin x|+C。","children":[],"note":""},{"title":"∫sec x dx=ln|sec x+tan x|+C；∫csc x dx=ln|csc x−cot x|+C。","children":[],"note":""},{"title":"\\(\\int\\frac{\\mathrm dx}{\\sqrt{1-x^2}}=\\arcsin x+C\\)。","children":[],"note":""},{"title":"∫dx/√(a²−x²)=arcsin(x/a)+C（a>0）。","children":[],"note":""},{"title":"∫dx/(a²+x²)=(1/a)arctan(x/a)+C（a>0）。","children":[],"note":""},{"title":"(∫f(x)dx)′=f(x)；d∫f(x)dx=f(x)dx。","children":[],"note":""},{"title":"∫F′(x)dx=F(x)+C；∫dF(x)=F(x)+C。","children":[],"note":""},{"title":"∫k f(x)dx=k∫f(x)dx（k为常数）；∫[f(x)±g(x)]dx=∫f(x)dx±∫g(x)dx。","children":[],"note":""},{"title":"幂函数公式不能用于指数μ=−1，μ=−1时应改用ln|x|。","children":[],"note":""},{"title":"含复合函数时不能直接套基本式，要检查内层导数并补系数。","children":[],"note":""},{"title":"不定积分最后必须写+C；含1/x时对数必须写绝对值。","children":[],"note":""}],"note":""}],"note":""},{"title":"3.2 定积分","children":[{"title":"定积分概念与性质","children":[{"title":"用分割、求和、取极限理解定积分。区分带符号的定积分和非负面积。","children":[],"note":""},{"title":"可加性、上下限交换变号、线性、比较与估值。","children":[],"note":""},{"title":"对称区间：可积奇函数积分为 0；可积偶函数为右半段积分的 2 倍。","children":[],"note":""}],"note":""},{"title":"定积分计算与变限","children":[{"title":"牛顿–莱布尼茨：\\(\\int_a^b f(x)\\,\\mathrm dx=F(b)-F(a)\\)。先代上限，再减下限。","children":[],"note":""},{"title":"上限 g(x) 的积分求导要乘 g′(x)；上下限都变时分别求导，减去下限贡献。","children":[],"note":""},{"title":"遇分段、绝对值、交点先拆区间。反常积分用极限定义，多个异常点要分别判断。","children":[],"note":""}],"note":""},{"title":"定积分｜定义、几何意义、性质与变限积分","children":[{"title":"本节先建立定积分的含义，再把“面积、对称性、区间拆分、变上限/下限”变成可直接做题的规则。","children":[],"note":""},{"title":"定积分既可以表示几何面积，也可以表示带符号的面积代数和：图像在 x 轴上方取正、下方取负。","children":[],"note":""},{"title":"做题先判断：题目是求数值、求面积、利用奇偶性，还是对含积分号的函数求导。","children":[],"note":""},{"title":"在区间 [a,b] 上，∫_a^b f(x)dx 中，a 是积分下限，b 是积分上限，f(x) 是被积函数，f(x)dx 是被积表达式，x 是积分变量。","children":[],"note":""},{"title":"积分值与被积函数、积分区间有关；积分变量只是记号，∫_a^b f(x)dx=∫_a^b f(t)dt=∫_a^b f(u)du。","children":[],"note":""},{"title":"当 f(x) 在 [a,b] 上可积时，称 f(x) 在该区间上可积。","children":[],"note":""},{"title":"不要把积分变量 x、t、u 当成不同的函数；改变量名时上下限和被积函数必须一起对应。","children":[],"note":""},{"title":"若 f(x)≥0，∫_a^b f(x)dx 等于曲线 y=f(x)、x 轴和两条竖线围成的面积。","children":[],"note":""},{"title":"若 f(x)≤0，定积分等于该面积的相反数。","children":[],"note":""},{"title":"若图像有上有下，定积分等于各部分“上方面积减下方面积”的代数和；题目问“几何面积”时要把每一块都取正后相加。","children":[],"note":""},{"title":"定积分为 0 不等于图像下没有面积，可能是正负面积抵消。","children":[],"note":""},{"title":"换限：∫_a^a f(x)dx=0；∫_a^b f(x)dx=-∫_b^a f(x)dx。","children":[],"note":""},{"title":"线性：∫_a^b kf(x)dx=k∫_a^b f(x)dx；∫_a^b[f(x)±g(x)]dx=∫_a^b f(x)dx±∫_a^b g(x)dx。","children":[],"note":""},{"title":"区间可加：若 c∈[a,b]，则∫_a^b f(x)dx=∫_a^c f(x)dx+∫_c^b f(x)dx。","children":[],"note":""},{"title":"若 f(x) 为奇函数且区间为 [-a,a]，∫_-a^a f(x)dx=0；若 f(x) 为偶函数，∫_-a^a f(x)dx=2∫_0^a f(x)dx。","children":[],"note":""},{"title":"先同时检查“函数奇偶性”和“上下限是否关于原点对称”；只有其中一个满足不能套公式。","children":[],"note":""},{"title":"∫_0^a√(a²-x²)dx 对应半径 a 的四分之一圆，结果为 πa²/4。","children":[],"note":""},{"title":"遇到 √[9-x²]、√[x(2-x)] 这类根式，先平方并配方，把曲线识别为圆；再按给出的区间确定是半圆、四分之一圆还是其一部分。","children":[],"note":""},{"title":"形如 ∫_-a^a[f(x)+f(-x)]dx，可用替换 x=-t 或把区间拆成 [-a,0] 与 [0,a] 来化成 2∫_0^a f(x)dx。","children":[],"note":""},{"title":"图形题必须带上区间判断，不能只看到圆的方程就直接写整圆面积。","children":[],"note":""},{"title":"若 F(x)=∫_a^x f(t)dt，则 F′(x)=f(x)。","children":[],"note":""},{"title":"若 F(x)=∫_a^{h(x)}f(t)dt，则 F′(x)=f(h(x))h′(x)。","children":[],"note":""},{"title":"若 F(x)=∫_{g(x)}^{h(x)}f(t)dt，则 F′(x)=f(h(x))h′(x)-f(g(x))g′(x)。","children":[],"note":""},{"title":"上限求导取正，下限求导取负；外层端点含 x 时还要乘端点的导数。","children":[],"note":""},{"title":"积分变量不能与上下限中的函数变量混淆：积分号内部优先使用 t、u 等哑变量。","children":[],"note":""},{"title":"“对称区间，偶倍奇零”只用于定积分，不用于不定积分。","children":[],"note":""},{"title":"题目问面积时，x 轴下方部分要取绝对值；题目问定积分值时保留正负。","children":[],"note":""}],"note":""},{"title":"定积分｜牛顿-莱布尼茨公式与直接计算","children":[{"title":"若 F′(x)=f(x)，则 ∫_a^b f(x)dx=F(x)|_a^b=F(b)-F(a)。","children":[],"note":""},{"title":"定积分不需要写 +C：上下限相减后，原函数中的任意常数会抵消。","children":[],"note":""},{"title":"这条公式把定积分转回不定积分：先求原函数，后代上、下限。","children":[],"note":""},{"title":"先写清 F(x)，再代 F(b)-F(a)，不要把下限代入后漏掉外面的减号。","children":[],"note":""},{"title":"第一步：判断被积函数是否需要化简、展开、拆项或分段。","children":[],"note":""},{"title":"第二步：求每一项的原函数 F(x)。","children":[],"note":""},{"title":"第三步：严格写成 F(b)-F(a)，括号内整体代入。","children":[],"note":""},{"title":"第四步：核对符号、端点和结果是否符合大致的正负或面积大小。","children":[],"note":""},{"title":"定积分不写积分常数 C；原函数中的 ln、根式等仍要遵守它们本身的定义条件。","children":[],"note":""},{"title":"被积函数是多项式、指数、三角基本函数或它们的线性组合时，利用线性性质逐项积分。","children":[],"note":""},{"title":"例如 ∫_-1^1[e^x+2x/(1+x²)]dx 可以拆开；其中 2x/(1+x²) 的原函数是 ln(1+x²)。","children":[],"note":""},{"title":"遇到 x(x-2)² 先展开成 x³-4x²+4x，再逐项积分；不要把乘积错误地拆为两个积分。","children":[],"note":""},{"title":"乘积和商一般不能直接“各自积分”；只有加减与常数倍可以直接拆。","children":[],"note":""},{"title":"若 f(x) 在 c 处分段，且 c∈(a,b)，必须写 ∫_a^b f(x)dx=∫_a^c f(x)dx+∫_c^b f(x)dx。","children":[],"note":""},{"title":"每一段只使用自己区间内的表达式，端点归属不影响单点处的定积分值，但书写必须与题设一致。","children":[],"note":""},{"title":"算完各段再相加，不能在整段区间上只代一个分支。","children":[],"note":""},{"title":"看到分段函数先找“分界点是否落在积分区间内”；落在区间外时无需拆。","children":[],"note":""},{"title":"求 ∫_0^2 f(x)dx 且 f(x) 为分段函数：按分界点 1 拆成两段，再分别代原函数。","children":[],"note":""},{"title":"求 ∫_0^1x(x-2)²dx：先展开，再求原函数 x⁴/4-4x³/3+2x²，最后代 1 和 0。","children":[],"note":""},{"title":"含 ln 的定积分可优先判断能否认出分子为分母导数，再使用凑微分或直接代原函数。","children":[],"note":""},{"title":"F(b)-F(a) 中 a 的代入必须整体加括号，特别是 a 为负数时。","children":[],"note":""},{"title":"定积分有上下限，不能像不定积分一样写 +C。","children":[],"note":""},{"title":"分段计算时不要遗漏某一段，也不要把分界点当成积分变量。","children":[],"note":""}],"note":""},{"title":"定积分｜换元法、分部积分法与综合计算","children":[{"title":"若 x=φ(t)，当 x=a、b 时分别求出 t=α、β，则 ∫_a^b f(x)dx=∫_α^β f[φ(t)]φ′(t)dt。","children":[],"note":""},{"title":"换元后可直接用新上下限完成计算，不需要再把 t 换回 x；这是定积分与不定积分的明显区别。","children":[],"note":""},{"title":"若仍使用原上下限，就必须在最后把变量还原；两种做法只能选一种，不能混用。","children":[],"note":""},{"title":"定积分换元的第一动作是写清“x=a 时 t=α；x=b 时 t=β”。","children":[],"note":""},{"title":"含 √(x+1) 时可令 t=√(x+1)；含 √(4-x²) 时可令 x=2sin t；代换目标是把根式和 dx 一起化简。","children":[],"note":""},{"title":"形如 1/[x(1+ln x)]、1/[x√(3+ln x)]，优先令 u=1+ln x 或 u=3+ln x。","children":[],"note":""},{"title":"遇到 sin x cos x、cos x sin²x 等，优先把其中一个三角函数与 dx 凑成 d(sin x) 或 d(cos x)。","children":[],"note":""},{"title":"换元后若仍留下 x，说明 dx 或某个因子没有完全替换。","children":[],"note":""},{"title":"∫_0^(π/2)sin^n xdx 与 ∫_0^(π/2)cos^n xdx 可用华里士公式处理；n 为奇数和偶数时形式不同。","children":[],"note":""},{"title":"简单题可先用恒等式降幂，例如 sin²x=(1-cos2x)/2。","children":[],"note":""},{"title":"题目若区间是 [0,π/2]，不要把奇偶函数对称区间的结论搬过来使用。","children":[],"note":""},{"title":"公式：∫_a^b u dv=uv|_a^b-∫_a^b v du。","children":[],"note":""},{"title":"选择 u 使它求导变简单，选择 dv 使它容易积分；x·sin x、x·sec²x、ln x 等常用分部积分。","children":[],"note":""},{"title":"例：∫_0^1xsin xdx=[-xcos x]_0^1+∫_0^1cos xdx=sin1-cos1。","children":[],"note":""},{"title":"分部积分后的边界项必须写 uv|_a^b；不能只写 uv 后忘记代上下限。","children":[],"note":""},{"title":"先看能否直接套牛顿-莱布尼茨；不行再看分子是否为分母或根式内层的导数。","children":[],"note":""},{"title":"根式题判断是否适合三角代换；x·三角函数、对数·多项式、幂函数·三角函数优先考虑分部积分。","children":[],"note":""},{"title":"有对称区间时先用奇偶性筛掉可消去的部分，再决定是否换元或分部。","children":[],"note":""},{"title":"定积分换元漏换上下限是最高频错误。","children":[],"note":""},{"title":"分部积分后仍是定积分，不加 +C。","children":[],"note":""},{"title":"三角代换的角度范围要与原积分区间对应，避免根号正负号错误。","children":[],"note":""}],"note":""},{"title":"广义积分｜无穷区间与瑕点积分的收敛性","children":[{"title":"∫_a^∞f(x)dx 定义为 lim_(b→∞)∫_a^b f(x)dx。","children":[],"note":""},{"title":"∫_-∞^b f(x)dx 定义为 lim_(a→-∞)∫_a^b f(x)dx。","children":[],"note":""},{"title":"∫_-∞^∞f(x)dx 必须拆为两段：∫_-∞^c f(x)dx+∫_c^∞f(x)dx；两段都收敛才称整体收敛。","children":[],"note":""},{"title":"不能把 -∞ 和 +∞ 直接代进原函数；必须先保留有限端点，再取极限。","children":[],"note":""},{"title":"若 f(x) 在端点 a 或 b 无定义，称该端点为瑕点；例如 1/√(x-a)、1/(x-a) 等。","children":[],"note":""},{"title":"瑕点在 a：∫_a^b f(x)dx=lim_(t→a+)∫_t^b f(x)dx。","children":[],"note":""},{"title":"瑕点在 b：∫_a^b f(x)dx=lim_(t→b-)∫_a^t f(x)dx。","children":[],"note":""},{"title":"瑕点 c∈(a,b)：必须拆为 lim_(t→c-)∫_a^t f(x)dx+lim_(t→c+)∫_t^b f(x)dx。","children":[],"note":""},{"title":"中间瑕点必须左右分别取极限，不能用一次跨越瑕点的积分代替。","children":[],"note":""},{"title":"计算完有限区间积分后再取极限；极限为有限实数，广义积分收敛；极限不存在或为无穷大，广义积分发散。","children":[],"note":""},{"title":"例如 ∫_0^∞3xe^-x²dx 收敛，因原函数为 -3e^-x²/2，极限存在。","children":[],"note":""},{"title":"例如 ∫_e^∞dx/[x ln√x] 的结果含 ln(ln x)，随 x→∞ 发散。","children":[],"note":""},{"title":"“被积函数趋于 0”不是积分一定收敛的充分条件，仍要按定义算极限。","children":[],"note":""},{"title":"先找反常点：无穷上限、无穷下限、分母为 0、根号内为 0 等。","children":[],"note":""},{"title":"把每个反常点用一个参数截断成正常定积分。","children":[],"note":""},{"title":"计算正常定积分后，分别写极限并判定收敛/发散。","children":[],"note":""},{"title":"选择题先找“哪一项的极限发散”，避免只看积分号内函数大小。","children":[],"note":""},{"title":"∞ 不是一个普通数，不能写 F(∞)-F(a)。","children":[],"note":""},{"title":"左右瑕点积分只要有一侧发散，整体就发散。","children":[],"note":""},{"title":"不要用“正负抵消”掩盖两侧分别发散的情况。","children":[],"note":""}],"note":""},{"title":"定积分｜含变限积分求导与综合复盘","children":[{"title":"F(x)=∫_a^x f(t)dt 时，F′(x)=f(x)。","children":[],"note":""},{"title":"F(x)=∫_x^a f(t)dt 时，F′(x)=-f(x)。","children":[],"note":""},{"title":"F(x)=∫_a^{h(x)}f(t)dt 时，F′(x)=f(h(x))h′(x)。","children":[],"note":""},{"title":"F(x)=∫_{g(x)}^{h(x)}f(t)dt 时，F′(x)=f(h(x))h′(x)-f(g(x))g′(x)。","children":[],"note":""},{"title":"口诀：上限为正、下限为负、端点含 x 再乘导数。","children":[],"note":""},{"title":"积分号内的 t 是积分变量，外面的 x 是自变量。写 F(x)=∫_{2x}^{e^-x}ln(1+t²)dt 时，先对端点分别应用公式，不能把 t 直接当 x。","children":[],"note":""},{"title":"当上下限都含 x 时，每一项都要代入对应端点，再分别乘导数，最后相减。","children":[],"note":""},{"title":"建议固定用 t、u 作积分变量，可避免把“被积函数变量”和“求导变量”混写。","children":[],"note":""},{"title":"若题目给出 f(x)=ln x-∫_1^a f(t)dt 一类关系，可先把定积分看成常数 A，再建立关于 A 的方程。","children":[],"note":""},{"title":"含 ∫_a^x 与普通函数相加时，先按变限积分求导，再按普通求导法则处理。","children":[],"note":""},{"title":"若积分区间是对称区间，可先利用奇偶性或对称替换简化，再进行后续计算。","children":[],"note":""},{"title":"检查积分变量是否与外变量分开。","children":[],"note":""},{"title":"检查上、下限符号：下限导数项前必有减号。","children":[],"note":""},{"title":"检查端点导数是否全部乘上。","children":[],"note":""},{"title":"最后把结果整理为关于 x 的函数，必要时核对定义域。","children":[],"note":""},{"title":"F′(x)=f(x) 只适用于上限恰好为 x、下限为常数的最基本形式。","children":[],"note":""},{"title":"上限 e^-x、2x、x² 等都必须补链式法则。","children":[],"note":""},{"title":"遇到上下限颠倒时，可先换限带负号，也可直接套“上减下”公式，但不可两次变号。","children":[],"note":""}],"note":""}],"note":""},{"title":"3.3 定积分的应用","children":[{"title":"定积分应用","children":[{"title":"直角坐标求面积：上减下或右减左，先解交点、画草图、必要时分段。","children":[],"note":""},{"title":"旋转体体积用截面积积分。垫片法为 \\(\\pi\\int (R^2-r^2)\\,\\mathrm dx\\)，半径是到旋转轴的距离。","children":[],"note":""},{"title":"弧长常用 ∫√(1+[y′(x)]²) dx。应用题先辨积分变量、区间和微元的含义。","children":[],"note":""}],"note":""},{"title":"面积与体积的列式顺序","children":[{"title":"先画边界、标交点，判断竖切还是横切更省分段。","children":[],"note":""},{"title":"以 x 为变量时面积为 ∫(y上−y下)dx。","children":[],"note":""},{"title":"以 y 为变量时面积为 ∫(x右−x左)dy。","children":[],"note":""},{"title":"旋转轴穿过区域时逐段判断内半径是否为零。","children":[],"note":""}],"note":""}],"note":""}],"note":"认原函数 → 选积分方法 → 分清净值与几何量"},{"title":"英语 01 · 基础语法","children":[{"title":"1.1 句子结构","children":[{"title":"句子结构","children":[{"title":"先定位谓语，再找主语，区分宾语、表语、宾补与修饰成分。","children":[],"note":""},{"title":"五种常见基本句型：S+V、S+V+O、S+V+P、S+V+IO+DO、S+V+O+OC。","children":[],"note":""},{"title":"看陈述、疑问、祈使和感叹的语序。What a nice day! / How nice it is!","children":[],"note":""}],"note":""},{"title":"句子成分核心","children":[{"title":"句子的主干由主语和谓语构成。","children":[],"note":""},{"title":"常见补充成分包括宾语、表语、定语、状语、宾语补足语和同位语。","children":[],"note":""},{"title":"宾语补足语补充说明宾语；表语说明主语的身份、状态或特征。","children":[],"note":""},{"title":"名词、代词、数词、名词化形容词、不定式、动名词、主语从句以及形式主语it都可以充当主语。","children":[],"note":""}],"note":""},{"title":"五种基本句型","children":[{"title":"主语+谓语：SV，谓语通常是不及物动词。","children":[],"note":""},{"title":"主语+谓语+宾语：SVO，谓语通常是及物动词。","children":[],"note":""},{"title":"主语+系动词+表语：SVP。","children":[],"note":""},{"title":"主语+谓语+间接宾语+直接宾语：SVOO。","children":[],"note":""},{"title":"主语+谓语+宾语+宾语补足语：SVOC。","children":[],"note":""}],"note":""},{"title":"句子成分例句笔记","children":[{"title":"The cat chased the mouse：the mouse是宾语。","children":[],"note":""},{"title":"The cat found the mouse tricky：tricky补充说明the mouse，是宾语补足语。","children":[],"note":""},{"title":"The mouse is tricky：tricky说明主语，是表语（主语补足语）。","children":[],"note":""},{"title":"The cat caught the tricky mouse swiftly：tricky修饰mouse，是定语；swiftly说明动作方式，是状语。","children":[],"note":""},{"title":"The cat caught its prey, a tricky mouse, swiftly：a tricky mouse解释its prey，是同位语。","children":[],"note":""},{"title":"名词、代词、数词、名词化形容词、不定式、动名词、主语从句以及形式主语it均可作主语。","children":[],"note":""},{"title":"主语说明谁或什么；谓语说明动作、状态或存在；宾语是动作承受者；表语说明主语身份或特征；定语修饰名词；状语修饰动词、形容词、副词或整句；补语补充主语或宾语。","children":[],"note":""},{"title":"五大基本句型：S+V；S+V+O；S+V+P；S+V+IO+DO；S+V+O+OC。先找谓语，再判断其后成分，不能按中文词序硬套。","children":[],"note":""},{"title":"系动词后接表语而不是宾语；双宾语可改为S+V+物+to/for+人；宾补与宾语构成逻辑上的主谓或主表关系。","children":[],"note":""},{"title":"简单句只有一个主谓核心；并列句由并列连词连接；复合句含从句。判断句型先划分主句和从句，再看每个谓语。","children":[],"note":""}],"note":""},{"title":"系动词与主系表笔记","children":[{"title":"状态：be（am/is/are/was/were），说明身份或状态。","children":[],"note":""},{"title":"感官：look、sound、smell、taste、feel。","children":[],"note":""},{"title":"变化：become、get、turn、go、grow、fall。","children":[],"note":""},{"title":"持续：keep、remain、stay、stand、lie。","children":[],"note":""},{"title":"表象：seem、appear。","children":[],"note":""},{"title":"结果：prove、turn out。","children":[],"note":""},{"title":"The story sounds interesting：sounds是系动词，interesting是表语。","children":[],"note":""},{"title":"The cat kept quiet：kept表示保持某种状态，是系动词。","children":[],"note":""},{"title":"The cat kept the mouse in a cage：kept表示把老鼠关在笼中，是实义动词。","children":[],"note":""},{"title":"The mouse got scared：got表示状态变化，是系动词；The cat got the mouse at last中的got是实义动词。","children":[],"note":""}],"note":""},{"title":"双宾语与宾语补足语笔记","children":[{"title":"My mom bought me a puppy：me为间接宾语，a puppy为直接宾语。","children":[],"note":""},{"title":"常见转换：give sb sth = give sth to sb；buy sb sth = buy sth for sb。","children":[],"note":""},{"title":"I grant you an end与My boss promised me a higher position and better welfare都属于双宾语结构。","children":[],"note":""},{"title":"The loud noise drove everyone crazy：crazy说明everyone的状态。","children":[],"note":""},{"title":"You made Shilan suffer bitterly：suffer为不带to的不定式作宾补。","children":[],"note":""},{"title":"The news left the whole family in deep sorrow：介词短语in deep sorrow作宾补。","children":[],"note":""},{"title":"若后两个成分是“人+物”，多为双宾语；若后一个成分在描述前面的宾语，多为宾语补足语。","children":[],"note":""}],"note":""},{"title":"句子分类笔记","children":[{"title":"简单句：只有一套主谓结构，如The mouse is tricky。","children":[],"note":""},{"title":"并列复合句：两个或以上并列分句用and、but、or等连接，如The mouse is tricky, but the cat caught it。","children":[],"note":""},{"title":"主从复合句：含主句与从句，如The cat caught the mouse, who is tricky。","children":[],"note":""},{"title":"陈述句：陈述事实或观点。","children":[],"note":""},{"title":"疑问句：包括一般疑问句、特殊疑问句、选择疑问句、反意疑问句。","children":[],"note":""},{"title":"祈使句：表示命令、请求或建议，常省略主语you。","children":[],"note":""},{"title":"感叹句：常用What或How引导，表达强烈感情。","children":[],"note":""}],"note":""},{"title":"句子成分及句子类型（扫描笔记）","children":[{"title":"主语+谓语（SV）：谓语通常是不及物动词，如His friend left。","children":[],"note":""},{"title":"主语+谓语+宾语（SVO）：谓语通常是及物动词，如He missed his friends。","children":[],"note":""},{"title":"主语+谓语+间接宾语+直接宾语（SVOO）：如He sent his friend a gift。","children":[],"note":""},{"title":"主语+谓语+宾语+宾语补足语（SVOC）：如It made his friend happy。","children":[],"note":""},{"title":"主语+系动词+表语（SVP）：如They are best friends。","children":[],"note":""},{"title":"英语常见句子成分包括主语、谓语、宾语、表语、宾语补足语、定语、状语和同位语。","children":[],"note":""},{"title":"主语是动作的发出者或句子说明的对象；谓语说明主语的动作或状态。","children":[],"note":""},{"title":"宾语是谓语动作的承受者；表语说明主语的身份、特征或状态；宾补补充说明宾语。","children":[],"note":""},{"title":"定语修饰名词或代词；状语说明时间、地点、方式、原因、结果等；同位语解释说明前面的名词。","children":[],"note":""},{"title":"名词、代词、数词、the+形容词、不定式、动名词和从句都可以作主语。","children":[],"note":""},{"title":"形式主语it可替代较长的不定式或从句，如It is important to study English every day。","children":[],"note":""},{"title":"英语句子必须有谓语动词；一个独立分句通常只有一套谓语结构。","children":[],"note":""},{"title":"实义动词、助动词+实义动词、情态动词+实义动词、系动词+表语都可构成谓语；非谓语动词本身不能独立充当谓语。","children":[],"note":""},{"title":"宾语可由名词、代词、不定式、动名词、复合宾语结构或宾语从句等充当。","children":[],"note":""},{"title":"表语位于系动词之后，可由名词、代词、形容词、介词短语、动名词、不定式或表语从句充当。","children":[],"note":""},{"title":"宾语补足语说明宾语的身份或状态，如We elected him president、The news made her happy。","children":[],"note":""},{"title":"定语既可前置，也可后置；状语常按“方式+地点+时间”排列，地点和时间通常由小到大。","children":[],"note":""},{"title":"同位语紧跟名词，对其进行解释说明；同位语从句常用that引导。","children":[],"note":""}],"note":""},{"title":"句子类型（扫描笔记）","children":[{"title":"简单句只有一套主谓结构；并列主语或并列谓语仍可属于简单句。","children":[],"note":""},{"title":"并列句由并列连词连接两个或多个结构并列、互不从属的简单句。","children":[],"note":""},{"title":"主从复合句包含主句和从句，从句由连接词引导并在主句中充当某种成分。","children":[],"note":""},{"title":"判断长句时先找谓语动词和连接词，再确定每一套主谓结构。","children":[],"note":""},{"title":"并列或递进：and、both...and...、not only...but also...、neither...nor...。","children":[],"note":""},{"title":"选择：or、either...or...。","children":[],"note":""},{"title":"转折或对比：but、yet、while、whereas。","children":[],"note":""},{"title":"因果：for、so、therefore、thus。","children":[],"note":""},{"title":"从句可作主语、宾语、表语、同位语、定语或状语。","children":[],"note":""},{"title":"连接词之后通常出现新的主谓结构；找从句时可先圈连接词，再找从句谓语。","children":[],"note":""},{"title":"同位语从句解释抽象名词的具体内容；定语从句修饰前面的名词；状语从句说明时间、原因、条件等。","children":[],"note":""},{"title":"课堂讲义给出的“谓语动词个数=连接词个数+1”可作为基础长句分析的辅助方法，但仍要结合省略、并列和非谓语结构判断。","children":[],"note":""},{"title":"陈述句用于陈述事实或观点，分肯定句和否定句。","children":[],"note":""},{"title":"疑问句包括一般疑问句、特殊疑问句、选择疑问句和反意疑问句。","children":[],"note":""},{"title":"祈使句以动词原形开头，通常省略主语you，用于命令、请求、建议或提醒。","children":[],"note":""},{"title":"感叹句常用What或How引导：What修饰名词，How修饰形容词或副词。","children":[],"note":""}],"note":""}],"note":""},{"title":"1.2 名词与代词","children":[{"title":"名词与代词","children":[{"title":"名词：可数、不可数、单复数、所有格。information、advice、equipment 通常不可数。","children":[],"note":""},{"title":"代词：主格、宾格、物主、反身、指示和不定代词。形容词性物主代词后接名词，名词性可独用。","children":[],"note":""},{"title":"both / either / neither 常指两者；all / none 看范围。another、other、the other 看是否特指及剩余数量。","children":[],"note":""}],"note":""},{"title":"双重所有格","children":[{"title":"双重所有格：of + 名词性物主代词或's所有格。","children":[],"note":""},{"title":"基本结构：a/an/any/some + 名词 + of + sb's/mine/yours/his。","children":[],"note":""}],"note":""},{"title":"of所有格","children":[{"title":"of所有格主要用于无生命事物，长串有生命名词也可以使用。","children":[],"note":""},{"title":"基本结构：the + 名词A + of + 所有者B。","children":[],"note":""},{"title":"翻译顺序通常是“B的A”。","children":[],"note":""}],"note":""},{"title":"'s所有格","children":[{"title":"规则复数名词一般在词尾加'，如Teachers' Day。","children":[],"note":""},{"title":"不规则复数名词后加's，如Children's Day。","children":[],"note":""},{"title":"表示各自所有时，各名词末尾都加's。","children":[],"note":""},{"title":"表示共有关系时，只在最后一个名词末尾加's。","children":[],"note":""},{"title":"表示某人家或店铺时，所有格后的名词可以省略。","children":[],"note":""}],"note":""},{"title":"既可修饰可数又可修饰不可数的限定词","children":[{"title":"all、most、some、any、a lot of、lots of、plenty of、enough、no、other既可修饰可数名词，也可修饰不可数名词。","children":[],"note":""},{"title":"a quantity of后的谓语单复数由后面的名词决定。","children":[],"note":""},{"title":"quantities of表示“大量的”时，谓语动词通常用复数。","children":[],"note":""}],"note":""},{"title":"只能修饰可数名词的限定词","children":[{"title":"few表示“几乎没有”，含否定意义；a few表示“有几个”，含肯定意义。","children":[],"note":""},{"title":"a number of后接复数名词，谓语动词用复数。","children":[],"note":""},{"title":"the number of后接复数名词，但谓语动词用单数。","children":[],"note":""},{"title":"many a和more than one后接单数名词，谓语动词用单数。","children":[],"note":""}],"note":""},{"title":"只能修饰不可数名词的限定词","children":[{"title":"little表示“几乎没有”，含否定意义；a little表示“有一点”，含肯定意义。","children":[],"note":""},{"title":"much、a great deal of、a large amount of、amounts of用于不可数名词。","children":[],"note":""}],"note":""},{"title":"可数名词单数变复数的不规则变化（1）","children":[{"title":"元音变化：man-men、woman-women、foot-feet、goose-geese、tooth-teeth、mouse-mice。","children":[],"note":""},{"title":"单复数同形：means、species、series、fish、sheep、deer。","children":[],"note":""},{"title":"只有复数形式：trousers、clothes、thanks、goods、glasses。","children":[],"note":""},{"title":"people、police、cattle等集合名词通常按复数使用。","children":[],"note":""}],"note":""},{"title":"可数名词单数变复数的不规则变化（2）","children":[{"title":"class、family、crowd、couple、group、team、audience可作单数强调整体，也可作复数强调成员。","children":[],"note":""},{"title":"部分名词复数有特殊含义：customs海关、times时代、spirits心情、drinks饮料、greens青菜、woods树林、works工厂/作品、forces军队。","children":[],"note":""},{"title":"合成名词有主体名词时，把主体名词变复数，如sons-in-law、passers-by、story-tellers。","children":[],"note":""},{"title":"无主体名词时通常把最后一部分变复数，如grown-ups；由man/woman作定语时两部分都变复数，如women singers、men doctors。","children":[],"note":""}],"note":""},{"title":"可数名词单数变复数的规则变化（1）","children":[{"title":"一般名词在词尾加-s。","children":[],"note":""},{"title":"以-s、-x、-ch、-sh结尾的名词加-es。","children":[],"note":""},{"title":"部分以-f或-fe结尾的名词变f/fe为v再加-es；chief、proof、roof等直接加-s。","children":[],"note":""},{"title":"辅音字母+y结尾，变y为i再加-es。","children":[],"note":""}],"note":""},{"title":"可数名词单数变复数的规则变化（2）","children":[{"title":"元音字母+y结尾直接加-s，如toy-toys、boy-boys。","children":[],"note":""},{"title":"辅音字母+o结尾常加-es，如heroes、potatoes、tomatoes；pianos、photos、autos、kilos加-s。","children":[],"note":""},{"title":"zero和volcano的复数两种形式均可。","children":[],"note":""},{"title":"元音字母+o结尾通常加-s，如radios、bamboos、zoos。","children":[],"note":""},{"title":"-th结尾通常加-s，如truths、mouths、months、paths。","children":[],"note":""}],"note":""},{"title":"复数表达不一样意义的名词","children":[{"title":"work表示“工作”，works可表示“作品、工厂”。","children":[],"note":""},{"title":"arm表示“胳膊”，arms表示“武器”。","children":[],"note":""},{"title":"cloth表示“布料”，clothes表示“衣服”。","children":[],"note":""},{"title":"custom表示“习俗”，customs表示“海关”。","children":[],"note":""},{"title":"glass表示“玻璃”，glasses表示“眼镜”。","children":[],"note":""},{"title":"good表示“好处”，goods表示“商品”；time表示“时间”，times表示“时期/时代”。","children":[],"note":""}],"note":""},{"title":"常见不可数名词第1组","children":[{"title":"work、weather、furniture、equipment、luggage/baggage、time、water、money、space、distance、energy在本组用法中通常按不可数名词使用。","children":[],"note":""}],"note":""},{"title":"常见不可数名词第2组","children":[{"title":"success、trouble、health、wealth、wisdom、patience、confidence、honesty、help、luck在本组用法中通常按不可数名词使用。","children":[],"note":""}],"note":""},{"title":"常见不可数名词第3组","children":[{"title":"advice、news、information、knowledge、progress、experience、education、practice、pollution、waste在本组用法中通常按不可数名词使用。","children":[],"note":""}],"note":""},{"title":"常见不可数名词第4组","children":[{"title":"bravery、kindness、politeness、fun、happiness、poverty、anger、jealousy、music、admiration、evidence在本组用法中通常按不可数名词使用。","children":[],"note":""}],"note":""},{"title":"名词的可数与不可数性","children":[{"title":"个体名词和集合名词通常可以用数目计算，属于可数名词。","children":[],"note":""},{"title":"物质名词和抽象名词一般无法直接用数目计算，属于不可数名词。","children":[],"note":""},{"title":"不可数名词一般没有复数形式；若出现复数，常表示种类、大量事物或特定区域。","children":[],"note":""}],"note":""},{"title":"名词分类体系总览","children":[{"title":"名词分为普通名词和专有名词。","children":[],"note":""},{"title":"普通名词中的可数名词包括个体名词和集合名词。","children":[],"note":""},{"title":"普通名词中的不可数名词包括物质名词和抽象名词。","children":[],"note":""},{"title":"people、police、cattle通常按复数处理；furniture、equipment、luggage、clothing通常不可数。","children":[],"note":""}],"note":""},{"title":"可数名词复数变化总表","children":[{"title":"一般名词加-s；以s、x、ch、sh结尾加-es。","children":[],"note":""},{"title":"辅音字母+y结尾变y为i加-es，元音字母+y结尾直接加-s。","children":[],"note":""},{"title":"部分f或fe结尾变为ves，但chief、proof、roof等直接加-s。","children":[],"note":""},{"title":"man-men、woman-women、foot-feet等属于不规则变化；sheep、deer、fish、series、species、means常单复数同形。","children":[],"note":""},{"title":"合成名词通常将主体名词变复数；woman/man作定语时常两部分都变复数。","children":[],"note":""}],"note":""},{"title":"抽象名词具体化与专有名词普通化","children":[{"title":"抽象名词表示抽象概念时通常不可数，表示一次具体经历、具体事物或类别时可以可数。","children":[],"note":""},{"title":"It is a pleasure和It is an honor中的pleasure、honor表示一件具体的事，可用不定冠词。","children":[],"note":""},{"title":"专有名词可普通名词化，表示同名者或具有某人物特征的人，并可出现复数。","children":[],"note":""}],"note":""},{"title":"名词数量限定词与主谓一致","children":[{"title":"many、few、a few、a number of等修饰可数名词；much、little、a little、a great deal of等修饰不可数名词。","children":[],"note":""},{"title":"a lot of、lots of、plenty of、a large quantity of等可修饰可数或不可数名词。","children":[],"note":""},{"title":"a number of加复数名词，谓语用复数；the number of加复数名词，谓语用单数。","children":[],"note":""},{"title":"many a和more than one后接单数名词，谓语用单数。","children":[],"note":""},{"title":"large amounts/quantities of作主语时通常接复数谓语；单数amount/quantity结构需看中心词和教材规则。","children":[],"note":""}],"note":""},{"title":"不可数名词的量化表达","children":[{"title":"不可数名词表示具体数量时，要使用计量结构，而不是直接加复数。","children":[],"note":""},{"title":"基本结构是“数词＋可数计量名词＋of＋不可数名词”。","children":[],"note":""},{"title":"常见搭配有a piece of advice/news/information/baggage、a bottle of water、a loaf of bread等。","children":[],"note":""},{"title":"数量大于1时，变化的是计量名词，如two bottles of water。","children":[],"note":""}],"note":""},{"title":"名词的格与三种所有格总表","children":[{"title":"有生命的人或动物常用's所有格，无生命事物常用of所有格，但时间、地点、国家、机构等也常用's。","children":[],"note":""},{"title":"规则复数名词只加撇号，不规则复数名词加's。","children":[],"note":""},{"title":"共同所有只在最后一个名词后加's；各自所有则每个名词后都加's。","children":[],"note":""},{"title":"双重所有格结构为of＋名词所有格或名词性物主代词。","children":[],"note":""},{"title":"a photo of Nana's表示Nana拥有的照片之一；a photo of Nana表示照片内容是Nana。","children":[],"note":""}],"note":""},{"title":"名词的句法功能与名词作定语","children":[{"title":"名词的格和位置反映其在句中的语法功能。","children":[],"note":""},{"title":"名词可以作主语、宾语、表语、同位语和定语。","children":[],"note":""},{"title":"名词作定语时通常用单数，如sports meeting、school gates、sales manager。","children":[],"note":""},{"title":"woman/man作定语时，若中心名词为复数，通常二者都变为复数。","children":[],"note":""}],"note":""},{"title":"抽象名词具体化","children":[{"title":"It’s an honor to be here. 中的an honor表示“一件荣耀的事/一种荣幸”，已经具体化，因此可以用冠词an。","children":[],"note":""},{"title":"抽象名词本来表示性质、状态、情感或动作，通常不可数。","children":[],"note":""},{"title":"在具体语境中，它可以转化为可数名词，表示具体的人、事情、物品、一次经历或一种类型。","children":[],"note":""},{"title":"抽象名词表示概念、性质或状态，具体化后可指具体的人、事、物，常需加不定冠词或改为复数。","children":[],"note":""},{"title":"experience可表示经验（不可数）或一次经历（an experience）；beauty可表示美（不可数）或美人／美景（a beauty）。","children":[],"note":""},{"title":"抽象名词前是否用a/an要看语境中是否指一个具体实例，不是看到名词就机械加冠词。","children":[],"note":""},{"title":"翻译时先判断中文是否出现“一种、一次、一个具体表现”等含义，再决定单复数和冠词。","children":[],"note":""}],"note":""},{"title":"名词（上）全方位","children":[{"title":"原资料开头先梳理英语语法：基础语法包括9大词性、8大句子成分、5大基本句型；高频语法围绕句子谓语动词展开，包括时态语态、主谓一致、虚拟语气、三大从句、非谓语和特殊句型。","children":[],"note":""},{"title":"实词可单独充当句子成分：名词、动词、形容词、副词、代词、数词；虚词一般不能单独充当句子成分：冠词、连词、介词。","children":[],"note":""},{"title":"名词：人、事、物、时间地点、抽象概念的名称。","children":[],"note":""},{"title":"名词分为专有名词和普通名词；普通名词包括个体名词、集合名词、物质名词、抽象名词。","children":[],"note":""},{"title":"专有名词表示人名、地名、月份、星期、组织机构、书刊名等。","children":[],"note":""},{"title":"原资料例：May / Peter / John Smith / Li Hua；China / Russia / America / the Great Wall / Chongqing / Beijing；January—December；Monday—Sunday；the United Nations / WTO；Christmas / Thanksgiving Day / the Spring Festival / the Mid-Autumn Festival / the Dragon Boat Festival；The Times / The Economist / Pride and Prejudice。","children":[],"note":""},{"title":"专有名词首字母要大写；虚词通常不大写，除非位于首词；书刊名虚词也按标题规则处理。","children":[],"note":""},{"title":"个体名词如 book, pen, table, student, teacher, computer, school, city；可以有单数和复数。","children":[],"note":""},{"title":"集合名词如 family, class, team, committee, group, government, army, party。","children":[],"note":""},{"title":"集合名词强调一个整体时，谓语用单数；强调其中成员时，谓语用复数。","children":[],"note":""},{"title":"My family is a big family.（整体）/ My family are watching TV.（成员）","children":[],"note":""},{"title":"补充 be：am 只用于 I；is 用于单数、第三人称单数；are 用于复数和第二人称。","children":[],"note":""},{"title":"物质名词表示物质、材料的总称，如 water, milk, wine, blood, money, wood, furniture, wind, gas, oxygen, glass, paper, meat；物质名词通常不可数。","children":[],"note":""},{"title":"部分物质名词加 -s 后词义发生变化：waters 水域、woods 森林、glasses 眼镜、papers 论文/文件等，应按词义判断。","children":[],"note":""},{"title":"抽象名词表示抽象概念，如 love, hope, happiness, news, confidence, dream, emotion, friendship, advice, health, time, trust, knowledge；抽象名词通常不可数。","children":[],"note":""},{"title":"个体名词和集合名词属于可数名词；可数名词有单数、复数两种形式。","children":[],"note":""},{"title":"数量＝1时用单数；数量＞1时用复数。","children":[],"note":""},{"title":"一般直接加 -s：book→books, apple→apples, student→students, map→maps, plan→plans。","children":[],"note":""},{"title":"以 s/sh/ch/x 结尾加 -es：bus→buses, box→boxes, watch→watches, dish→dishes；注意 stomach→stomachs。","children":[],"note":""},{"title":"辅音字母＋y：y→i＋es：city→cities, body→bodies, factory→factories, country→countries；元音字母＋y直接加 -s：boy→boys, toy→toys。","children":[],"note":""},{"title":"以 o 结尾：hero→heroes, tomato→tomatoes, potato→potatoes；piano→pianos, radio→radios；volcano→volcanos/volcanoes。","children":[],"note":""},{"title":"以 f/fe 结尾：常见 f/fe→v＋es，如 leaf→leaves, knife→knives, wife→wives, shelf→shelves；例外 roof→roofs, proof→proofs, chief→chiefs；scarf 可 scarves/scarfs。","children":[],"note":""},{"title":"单复数同形：deer, fish, sheep, Chinese, Japanese, Swiss, means, crossroads, species, headquarters。","children":[],"note":""},{"title":"改变元音：man→men, woman→women, foot→feet, tooth→teeth, goose→geese, mouse→mice, louse→lice。","children":[],"note":""},{"title":"加 -en/-ren：ox→oxen, child→children。","children":[],"note":""},{"title":"含 man/woman 且作为构词成分时，按资料规则变化：Englishman→Englishmen, policeman→policemen, policewoman→policewomen；German→Germans。","children":[],"note":""},{"title":"man/woman 修饰后面的名词且整体变复数时，前后通常都变：woman doctor→women doctors；但 man teacher→men teachers。","children":[],"note":""},{"title":"以连字符构成的复合词：有主体名词时把主体名词变复数，如 mother-in-law→mothers-in-law；没有主体名词时把最后一部分变复数，如 grown-up→grown-ups。","children":[],"note":""},{"title":"可数名词有单复数，可与a/an、数词、many/few搭配；不可数名词通常无复数，不能直接用a/an，需用a piece of、a bottle of等量词。","children":[],"note":""},{"title":"规则复数通常加-s/-es；辅音+y改为-ies，f/fe部分改为-ves；外来词和专有名词要按词典或课件规则判断。","children":[],"note":""},{"title":"常见不规则：man→men，woman→women，child→children，mouse→mice，tooth→teeth，foot→feet。复合名词通常在中心词处变复数。","children":[],"note":""},{"title":"集体名词表示整体时谓语常用单数，强调成员时可用复数（英式尤其常见）；family、team、class要结合语境。","children":[],"note":""},{"title":"主谓一致优先找真正主语，介词短语、定语从句和插入语不改变主语单复数。each/every/either/neither后接单数名词，both后接复数。","children":[],"note":""},{"title":"s所有格表示所属；共同所有格只在最后一个名词后加’s，分别所有格每个名词都加’s；无生命名词常用of结构。双重所有格为a friend of Tom’s，表示“汤姆的一个朋友”。","children":[],"note":""},{"title":"advice、information、furniture、equipment通常不可数；不能写advices，表达数量用pieces of advice。","children":[],"note":""}],"note":""},{"title":"名词（下）全方位","children":[{"title":"不可数名词没有复数形式，不能在词尾加 -s，前面不能直接接 a/an。","children":[],"note":""},{"title":"不可数名词可用“a/an/数词＋量词＋of＋名词”量化，如 a piece of advice / two pieces of advice；a cup of water / two bottles of water。","children":[],"note":""},{"title":"advice 不可数；suggestion“建议”为可数名词；advise / suggest 为动词。","children":[],"note":""},{"title":"原资料例句：I am writing to offer you some advice/suggestions.","children":[],"note":""},{"title":"所有格表示所属关系，即“……的……”。","children":[],"note":""},{"title":"原资料分为 ’s 所有格、of 结构所有格，并补充双重所有格。","children":[],"note":""},{"title":"主要用于有生命的名词，也可用于时间、距离、国家、城市、机构等。","children":[],"note":""},{"title":"Lily’s wallet；China’s development。","children":[],"note":""},{"title":"an/one hour’s drive = one-hour drive；two days’ holiday = two-day holiday；three hours’ walk = three-hour walk；five days’ holiday = five-day holiday。","children":[],"note":""},{"title":"复合形容词 one-hour / two-day 中名词用单数。","children":[],"note":""},{"title":"Children’s Day；Teachers’ Day；men’s room。","children":[],"note":""},{"title":"以 s 结尾的复数名词所有格，资料强调在词尾单独加撇号。","children":[],"note":""},{"title":"Lily’s and Lucy’s fathers are teachers.：分别所有，各自的 fathers。","children":[],"note":""},{"title":"Lily and Lucy’s father is a teacher.：共同所有，共同的 father。","children":[],"note":""},{"title":"记忆：n’s＋n’s 表个别所有；n＋n’s 表共同所有。","children":[],"note":""},{"title":"Tom and Jim’s room is on the second floor.；Tom’s and Jim’s rooms are on the second floor.","children":[],"note":""},{"title":"名词所有格可省略后面的地点名词：the barber’s（理发店）、the tailor’s（裁缝店）、the Green’s（格林家）。","children":[],"note":""},{"title":"of 结构所有格主要用于无生命的名词，基本结构为 A of B，B 的 A（A、B都为名词）。","children":[],"note":""},{"title":"The gate of our school is very beautiful.；the windows of the classroom；the roof of the house；the cover of the book。","children":[],"note":""},{"title":"China’s development = the development of China；the importance/significance of internet。","children":[],"note":""},{"title":"资料同时列出强调对应/指向关系的 to：the secret/key to success；the answer to the question；the key to the door。","children":[],"note":""},{"title":"双重所有格强调所属物是整体中的一部分。","children":[],"note":""},{"title":"结构：of＋名词’s / 名词性物主代词。","children":[],"note":""},{"title":"例如：a friend of my mother’s（我妈妈的一个朋友）。","children":[],"note":""}],"note":""},{"title":"名词与数量表达课堂笔记（手写）","children":[{"title":"可数名词和不可数名词","children":[],"note":""},{"title":"many、much及数量短语","children":[],"note":""},{"title":"单位词和量词结构","children":[],"note":""},{"title":"数量表达与主谓一致","children":[],"note":""}],"note":""},{"title":"反身代词","children":[{"title":"反身代词表示“某人自己”。","children":[],"note":""},{"title":"myself、ourselves、yourself、yourselves、himself、herself、itself、themselves分别对应不同人称与数。","children":[],"note":""},{"title":"by oneself表示“独自地”；enjoy oneself表示“玩得开心”；help oneself表示“随便吃/用”。","children":[],"note":""},{"title":"teach oneself表示“自学”；make oneself at home表示“别客气/随意”；say to oneself表示“心里想/自言自语”。","children":[],"note":""},{"title":"behave oneself表示“守规矩”；hurt oneself表示“伤到自己”；come to oneself表示“苏醒过来”；devote oneself to表示“致力于”。","children":[],"note":""}],"note":""},{"title":"代词分类与人称代词","children":[{"title":"代词主要包括人称、物主、反身、相互、指示、不定、疑问、连接和关系代词。","children":[],"note":""},{"title":"人称代词主格通常作主语，宾格通常作动词或介词的宾语。","children":[],"note":""},{"title":"第一、二、三人称均有单复数形式，第三人称单数还区分性别。","children":[],"note":""}],"note":""},{"title":"物主代词、反身代词与相互代词","children":[{"title":"形容词性物主代词后接名词，如my cat；名词性物主代词可独立使用，如The cat is mine。","children":[],"note":""},{"title":"反身代词由物主/宾格形式加-self或-selves构成，表示“某人自己”或强调。","children":[],"note":""},{"title":"each other通常表示两者之间，one another通常表示三者及以上之间；现代英语中二者有时可互换。","children":[],"note":""}],"note":""},{"title":"指示代词与数量不定代词综合","children":[{"title":"this/these表示近指，that/those表示远指；this/that为单数，these/those为复数。","children":[],"note":""},{"title":"many、few、a few用于可数名词复数；much、little、a little用于不可数名词。","children":[],"note":""},{"title":"some常用于肯定句和希望得到肯定回答的疑问句；any常用于否定句、疑问句及表示“任何”的语境。","children":[],"note":""},{"title":"each强调个体，可指两者及以上并可接of；every强调整体中的每一个，通常指三者及以上。","children":[],"note":""},{"title":"all/none用于三者及以上；both/either/neither用于两者。","children":[],"note":""}],"note":""},{"title":"other系列与复合不定代词","children":[{"title":"other通常作限定词修饰复数名词；the other表示两者中的另一个或其余特指对象。","children":[],"note":""},{"title":"others相当于other＋复数名词，表示泛指“其他人/物”；the others表示特指“其余全部”。","children":[],"note":""},{"title":"another表示三者或以上中的另一个，后接单数名词。","children":[],"note":""},{"title":"复合不定代词被形容词修饰时，形容词后置；作主语时谓语用单数。","children":[],"note":""}],"note":""},{"title":"替代词it、one、that、those","children":[{"title":"it指代前文出现的同一个具体事物。","children":[],"note":""},{"title":"one指代同类中的一个泛指可数名词单数。","children":[],"note":""},{"title":"that替代同类的单数可数名词或不可数名词，常用于比较结构。","children":[],"note":""},{"title":"those替代同类的复数可数名词，常用于比较结构。","children":[],"note":""}],"note":""},{"title":"疑问代词、连接代词与关系代词","children":[{"title":"疑问代词who、whom、whose、what、which用于构成特殊疑问句。","children":[],"note":""},{"title":"who通常作主语，whom通常作宾语，whose表示所属关系。","children":[],"note":""},{"title":"连接代词who/whom/whose/what/which及-ever形式可引导主语、宾语、表语或同位语从句。","children":[],"note":""},{"title":"关系代词who、whose、whom、that、which、as引导定语从句，并在从句中充当成分。","children":[],"note":""}],"note":""},{"title":"代词与限定词课堂笔记（手写）","children":[{"title":"other系列及不定代词","children":[],"note":""},{"title":"both、either、neither等辨析","children":[],"note":""},{"title":"all、none、each、every等数量关系","children":[],"note":""},{"title":"人称、物主、反身和指示代词","children":[],"note":""},{"title":"it、one、that、those等替代词","children":[],"note":""},{"title":"关系代词与连接代词","children":[],"note":""}],"note":""},{"title":"代词（上）全方位","children":[{"title":"代词（pron.）：代替名词。","children":[],"note":""},{"title":"原资料分类：人称代词、物主代词、反身代词、指示代词、不定代词、相互代词、疑问代词、关系代词（定语从句）、连接代词（名词性从句）。","children":[],"note":""},{"title":"主格作主语：I / we；you / you；he, she, it / they。","children":[],"note":""},{"title":"宾格作宾语：me / us；you / you；him, her, it / them。","children":[],"note":""},{"title":"第三人称单数作主语时，谓语动词用单数形式（动词＋s 等相应形式）。","children":[],"note":""},{"title":"it 除表示事物、动物“它”，还可表示婴儿、不明身份的人，也可表示时间、天气、温度、距离等。","children":[],"note":""},{"title":"The baby is crying. It must be hungry.；Someone is knocking the door. Go to see who it is.；It is 2 p.m. now.；It is sunny today.","children":[],"note":""},{"title":"It is/was 可以写成 It’s；注意 its（它的）与 it’s（it is/was）的区别。","children":[],"note":""},{"title":"it 作形式主语：To learn English is important. → It is important to learn English.；常见句型 It is/was＋adj.＋to do sth.","children":[],"note":""},{"title":"it 作形式宾语：I think it interesting to swim.；常见结构 sb. think/find/believe/consider＋it＋adj.＋to do。","children":[],"note":""},{"title":"形容词性物主代词：my, our, your, your, his, her, its, their；后面必须接名词。","children":[],"note":""},{"title":"名词性物主代词：mine, ours, yours, yours, his, hers, its, theirs；可单独使用。","children":[],"note":""},{"title":"名词性物主代词＝形容词性物主代词＋名词。","children":[],"note":""},{"title":"This is Mary’s watch. = This is her watch.；Where is mine? = Where is my umbrella?；Your school is bigger than ours (= our school).","children":[],"note":""},{"title":"第一、二人称：形容词性物主代词＋self/selves；第三人称：宾格＋self/selves。","children":[],"note":""},{"title":"myself, ourselves；yourself, yourselves；himself, herself, itself, themselves。","children":[],"note":""},{"title":"反身代词不能作主语，可以作主语的同位语以及宾语。","children":[],"note":""},{"title":"I myself study in the classroom.（同位语）/ I saw myself in the mirror.（宾语）","children":[],"note":""},{"title":"相关短语：by oneself 独自；enjoy oneself 玩得开心；help oneself to 请自便；devote oneself to 献身于；teach oneself 自学 = learn sth. by oneself。","children":[],"note":""},{"title":"this / these 表近指；that / those 表远指。","children":[],"note":""},{"title":"比较结构中可用 that/those 指代前面被比较的名词，避免重复：that 指代可数名词单数或不可数名词；those 指代可数名词复数。","children":[],"note":""},{"title":"The weather in Chongqing is hotter than that in Guiyang.","children":[],"note":""},{"title":"资料列出的常见比较结构：as...as；比较级＋than；be different from；be similar to；be equal to；be close to。","children":[],"note":""},{"title":"it：特指同一物，如 I have a pen. It is black.","children":[],"note":""},{"title":"one：泛指同类中的一个，如 I need a pen. Can you lend me one?；ones：泛指同类的多个。","children":[],"note":""},{"title":"the one：特指同类中特定的一个，通常有定语修饰；the ones：特指同类中特定的多个，通常有定语修饰。","children":[],"note":""},{"title":"原资料示例：Look at these dogs. The one with short tail is cute.；I don’t like these books. I prefer the ones you bought yesterday.","children":[],"note":""}],"note":""},{"title":"代词（下）全方位","children":[{"title":"常见不定代词：every, each, other, one, another, either, neither, both, all, none, everybody, everyone, everything, somebody, someone, something, anybody, anyone, anything, many, much, few, little 等。","children":[],"note":""},{"title":"复合不定代词按 some / any / no / every 与 thing / one / body 组合：something/anything/nothing/everything；someone/anyone/no one/everyone；somebody/anybody/nobody/everybody。","children":[],"note":""},{"title":"复合不定代词作主语，谓语用单数：Everything is possible.","children":[],"note":""},{"title":"形容词修饰复合不定代词时要后置：I have something important to tell you.","children":[],"note":""},{"title":"口诀：some 常用于肯定句；否定、疑问句常用 any；表达请求或建议时可用 some。","children":[],"note":""},{"title":"I have some money. / I don’t have any money. / Do you have any money?","children":[],"note":""},{"title":"Would you like some coffee? / Would you lend me some money?","children":[],"note":""},{"title":"any 用于肯定句可译为“任何的”：You can take any book which you like.","children":[],"note":""},{"title":"many 修饰可数名词复数：many books/students。","children":[],"note":""},{"title":"much 修饰不可数名词：much homework/money。","children":[],"note":""},{"title":"a lot of = lots of 表“很多、许多”，可接可数名词复数或不可数名词。","children":[],"note":""},{"title":"both：肯定两者；both...and... 两者都。","children":[],"note":""},{"title":"neither：否定两者；neither...nor... 既不……也不……。","children":[],"note":""},{"title":"either：两者之一；either...or... 要么……要么……。","children":[],"note":""},{"title":"all：肯定三者及以上；none：否定三者及以上。","children":[],"note":""},{"title":"other：其他的，other＋名词；Some students are singing and other students are dancing.","children":[],"note":""},{"title":"others = other＋复数名词，常用 some...others... 表“一些……其他的……”。","children":[],"note":""},{"title":"the other：两者中的另一个，常见 one...the other...。","children":[],"note":""},{"title":"the others：特定范围内其余的、剩余的，起到名词作用，后面不再接名词。","children":[],"note":""},{"title":"another：三者及以上中的另一个；也可表示“又一、再一”，如 another piece of cake；another two days。","children":[],"note":""},{"title":"有 a 表肯定“有一些”；无 a 表否定“几乎没有”。","children":[],"note":""},{"title":"a few / few 修饰可数名词；a little / little 修饰不可数名词。","children":[],"note":""},{"title":"I feel happy. I have a few friends.；I feel lonely. I have few friends.；There is a little water...；There is little water...。","children":[],"note":""},{"title":"every：原资料强调三者及以上；each：两者及以上。","children":[],"note":""},{"title":"each 可以与 of 搭配，而 every 不可以：Each of the students likes the movie.","children":[],"note":""},{"title":"Every student passed the exam. / Every house in the street is painted white. / There are trees on each side of the road.","children":[],"note":""},{"title":"each other：互相（两者）；one another：互相（三者及以上）。","children":[],"note":""},{"title":"Jack and Rose love each other.；The students in our class should help one another.","children":[],"note":""},{"title":"who 谁；whom 谁（who 的宾格）；whose 谁的；what 什么；which 哪一个。","children":[],"note":""},{"title":"例：Who are you? / Whom are you speaking to? / Whose book is this? / What is your name? / Which book do you like best?","children":[],"note":""},{"title":"We couldn’t buy anything because none of the shops were open.（none）","children":[],"note":""},{"title":"—tea or coffee? —Neither. I just prefer a glass of water.（Neither）","children":[],"note":""},{"title":"Can I have another piece, please?（another）","children":[],"note":""},{"title":"Some like running, some like swimming and others like ball games.（others）","children":[],"note":""},{"title":"Ten of them are girls and the others are boys.（the others）","children":[],"note":""},{"title":"She can speak a little French now.（a little）","children":[],"note":""}],"note":""},{"title":"指示代词：that与those","children":[{"title":"that可替代前文出现的可数名词单数或不可数名词。","children":[],"note":""},{"title":"those可替代前文出现的可数名词复数。","children":[],"note":""},{"title":"that/those后常接后置定语。","children":[],"note":""}],"note":""},{"title":"it、one、that、those辨析","children":[{"title":"it表示特指、同名同物。","children":[],"note":""},{"title":"one表示泛指、同名异物，只代可数名词单数。","children":[],"note":""},{"title":"that表示特指、同名异物，可代可数单数或不可数名词。","children":[],"note":""},{"title":"those表示特指、同名异物，只代可数名词复数。","children":[],"note":""}],"note":""},{"title":"one、the one、ones、the ones","children":[{"title":"one=a/an+单数名词。","children":[],"note":""},{"title":"the one=the+单数名词。","children":[],"note":""},{"title":"ones=复数名词，表示泛指。","children":[],"note":""},{"title":"the ones=the+复数名词，表示特指。","children":[],"note":""}],"note":""},{"title":"other、the other、others、the others、another","children":[{"title":"other泛指其他的，修饰可数复数或不可数名词。","children":[],"note":""},{"title":"the other可指两者中的另一个，或特定范围内其余全部。","children":[],"note":""},{"title":"others=other+复数名词，泛指其他部分，不再修饰名词。","children":[],"note":""},{"title":"the others=the other+复数名词，特指范围内其余全部。","children":[],"note":""},{"title":"another表示三个及以上范围中的另一个，修饰单数名词。","children":[],"note":""}],"note":""},{"title":"all、none、both、either、neither","children":[{"title":"all表示三者及以上全部肯定。","children":[],"note":""},{"title":"none表示三者及以上全部否定。","children":[],"note":""},{"title":"both表示两者都，接复数概念。","children":[],"note":""},{"title":"either表示两者任意一个，通常按单数。","children":[],"note":""},{"title":"neither表示两者都不，通常按单数。","children":[],"note":""}],"note":""},{"title":"each与every","children":[{"title":"each与every后接单数名词，谓语通常用单数。","children":[],"note":""},{"title":"each适用于两者及以上，强调个体。","children":[],"note":""},{"title":"every适用于三者及以上，强调整体。","children":[],"note":""},{"title":"each可接of短语、作同位语或置于句末表示分别。","children":[],"note":""},{"title":"not every表示部分否定：不是所有。","children":[],"note":""}],"note":""},{"title":"some与any","children":[{"title":"肯定陈述句多用some。","children":[],"note":""},{"title":"表示请求、邀请或客气语气的疑问句用some。","children":[],"note":""},{"title":"普通疑问句和否定句多用any。","children":[],"note":""},{"title":"any在肯定句中可表示任何。","children":[],"note":""}],"note":""},{"title":"few、a few、little、a little","children":[{"title":"few与a few修饰可数名词。","children":[],"note":""},{"title":"little与a little修饰不可数名词。","children":[],"note":""},{"title":"few/little表示否定：几乎没有。","children":[],"note":""},{"title":"a few/a little表示肯定：有一些。","children":[],"note":""}],"note":""},{"title":"many与much","children":[{"title":"many修饰可数名词复数。","children":[],"note":""},{"title":"much修饰不可数名词。","children":[],"note":""}],"note":""},{"title":"复合不定代词","children":[{"title":"常见复合不定代词包括something、anything、nothing、everything及-body/-one系列。","children":[],"note":""},{"title":"形容词修饰复合不定代词时必须后置。","children":[],"note":""},{"title":"复合不定代词作主语时谓语动词用单数。","children":[],"note":""}],"note":""}],"note":""},{"title":"1.3 冠词与数词","children":[{"title":"冠词与数词","children":[{"title":"a/an 按开头读音选：a university、an hour。the 表特指，也常用于序数词、最高级。","children":[],"note":""},{"title":"零冠词常见于泛指的复数名词或不可数名词，以及部分固定搭配。","children":[],"note":""},{"title":"具体数量：two hundred；泛指：hundreds of。复合定语：a five-minute walk，minute 用单数。","children":[],"note":""}],"note":""},{"title":"定冠词the：特指","children":[{"title":"the表示特指。","children":[],"note":""},{"title":"上文已提到的人或事物再次出现时用the。","children":[],"note":""},{"title":"双方都知道的对象用the。","children":[],"note":""},{"title":"独一无二的事物前常用the。","children":[],"note":""},{"title":"形容词最高级、序数词前常用the。","children":[],"note":""}],"note":""},{"title":"不定冠词a/an：泛指","children":[{"title":"a/an表示泛指“一个”。","children":[],"note":""},{"title":"a用于辅音音素开头的词前。","children":[],"note":""},{"title":"an用于元音音素开头的词前。","children":[],"note":""},{"title":"判断a/an看读音而不是首字母。","children":[],"note":""},{"title":"hour、honest前用an；university、European前用a。","children":[],"note":""}],"note":""},{"title":"零冠词：不用冠词","children":[{"title":"复数名词或不可数名词表示泛指时常用零冠词。","children":[],"note":""},{"title":"专有名词、语言、学科、球类、节日、月份、星期、三餐前常不用冠词。","children":[],"note":""},{"title":"by+交通工具常用零冠词。","children":[],"note":""},{"title":"固定搭配中也常出现零冠词。","children":[],"note":""}],"note":""},{"title":"定冠词与零冠词固定短语","children":[{"title":"in bed表示卧床/睡觉，in the bed表示在床上。","children":[],"note":""},{"title":"in hospital表示住院，in the hospital表示在医院里。","children":[],"note":""},{"title":"go to school表示上学，go to the school表示去学校。","children":[],"note":""},{"title":"go to church表示做礼拜，go to the church表示去教堂。","children":[],"note":""}],"note":""},{"title":"冠词总览与a/an发音判断","children":[{"title":"冠词分为不定冠词a/an、定冠词the和零冠词。","children":[],"note":""},{"title":"a用于辅音音素开头的单词前，an用于元音音素开头的单词前。","children":[],"note":""},{"title":"the在辅音音素前通常读/ðə/，在元音音素前通常读/ðiː/。","children":[],"note":""}],"note":""},{"title":"不定冠词a/an六类用法","children":[{"title":"泛指同类中不确定的一个。","children":[],"note":""},{"title":"第一次提到某人或某物。","children":[],"note":""},{"title":"单数名词表示一类人或物。","children":[],"note":""},{"title":"表示“一个”或“每一”。","children":[],"note":""},{"title":"用于固定表达或固定搭配。","children":[],"note":""},{"title":"a/an的位置可影响并列名词表示一人还是两人。","children":[],"note":""}],"note":""},{"title":"定冠词the八类用法","children":[{"title":"特指某个或某些确定的人或物。","children":[],"note":""},{"title":"双方都明白或上文已提到的人或物。","children":[],"note":""},{"title":"序数词、最高级以及only、very、same等词前。","children":[],"note":""},{"title":"世界上独一无二的事物前。","children":[],"note":""},{"title":"乐器名称前。","children":[],"note":""},{"title":"the+形容词表示一类人。","children":[],"note":""},{"title":"the+姓氏复数表示一家人。","children":[],"note":""}],"note":""},{"title":"零冠词七类用法与有the/无the辨析","children":[{"title":"多数专有名词前用零冠词。","children":[],"note":""},{"title":"复数名词表示一类人或物时用零冠词。","children":[],"note":""},{"title":"抽象名词表示一般概念时用零冠词；具体化时可用the或a/an。","children":[],"note":""},{"title":"三餐、球类、棋类、学科和语言前通常用零冠词。","children":[],"note":""},{"title":"季节、月份、节日、日期和星期前通常用零冠词。","children":[],"note":""},{"title":"by+交通工具单数时不用冠词。","children":[],"note":""},{"title":"部分固定表达使用零冠词。","children":[],"note":""}],"note":""},{"title":"冠词全方位","children":[{"title":"共5页，包含a/an发音判断、the常见用法、零冠词场景和固定短语辨析。","children":[],"note":""},{"title":"a/an表示泛指，the表示特指，零冠词表示名词前不使用冠词。","children":[],"note":""},{"title":"a/an表示泛指的一个、某一类中的一个；a用于辅音音素前，an用于元音音素前，判断依据是发音而非字母。a university、an hour是典型例子。","children":[],"note":""},{"title":"the表示特指、上文已提、双方都知道、独一无二、序数词/最高级、乐器、某些形容词名词化等。","children":[],"note":""},{"title":"零冠词常用于复数名词或不可数名词泛指、学科和球类、三餐、交通方式、抽象概念及专有名称；固定短语需整体记忆。","children":[],"note":""},{"title":"the+形容词可表示一类人（the rich），谓语通常按复数概念；the United States等国家名中的the属于专名。","children":[],"note":""},{"title":"地点名词有the与无the常改变语义：go to school强调上学这一功能，go to the school强调去学校这个地点。","children":[],"note":""}],"note":""},{"title":"冠词课堂完整笔记","children":[{"title":"冠词放在名词前起限定、说明作用，分不定冠词、定冠词和零冠词。","children":[],"note":""},{"title":"a/an按首音素判断；the在辅音音素前常读/ðə/，元音音素前常读/ðiː/。","children":[],"note":""},{"title":"泛指不确定的一个、首次提到、表示一类、表示“一/每”、固定表达。","children":[],"note":""},{"title":"用于特指、再次提及、序数词/最高级、独一无二事物、乐器、the+形容词、姓氏复数和固定表达。","children":[],"note":""},{"title":"用于专有名词、复数类指、抽象概念、球类/学科/语言、季节日期、by+交通工具和固定表达。","children":[],"note":""}],"note":""},{"title":"基数词构成与大数读法","children":[{"title":"1—10和11—19需熟记。","children":[],"note":""},{"title":"20—90的整十有固定拼写。","children":[],"note":""},{"title":"hundred、thousand、million、billion用于大数分级。","children":[],"note":""},{"title":"前有具体数字时，数量单位不用复数，也不用of。","children":[],"note":""},{"title":"表示概数时用hundreds/thousands/millions/billions of。","children":[],"note":""}],"note":""},{"title":"基数词的句法功能与数量单位","children":[{"title":"基数词可作主语、表语、宾语、定语或同位语。","children":[],"note":""},{"title":"dozen、score、hundred、thousand、million、billion前有具体数字时不用复数和of。","children":[],"note":""},{"title":"表示不确定概数时用复数形式＋of。","children":[],"note":""}],"note":""},{"title":"序数词构成与冠词使用","children":[{"title":"first、second、third需特殊记忆，其余通常在基数词后加-th并发生拼写变化。","children":[],"note":""},{"title":"序数词表示顺序时通常前加the。","children":[],"note":""},{"title":"序数词作副词时可不加the。","children":[],"note":""},{"title":"前面已有物主代词或其他限定词时不再加the。","children":[],"note":""},{"title":"a/an＋序数词表示“又一、再一”。","children":[],"note":""}],"note":""},{"title":"数词应用：分数、时间、日期、年代与年龄","children":[{"title":"分数：分子用基数词，分母用序数词；分子大于1时分母用复数。","children":[],"note":""},{"title":"时间：整点可用基数词＋o’clock；非整点可直接读或用past/to。","children":[],"note":""},{"title":"日期：英式“日月年”，美式“月日年”。","children":[],"note":""},{"title":"年代：in the＋整十的复数。","children":[],"note":""},{"title":"年龄：数字＋years old，at the age of＋数字，in one’s＋整十的复数。","children":[],"note":""}],"note":""},{"title":"数词应用：倍数、长宽高与主谓一致","children":[{"title":"倍数常用half、twice、three times等表达。","children":[],"note":""},{"title":"长宽高可用“数值＋单位＋long/wide/high”或“数值＋单位＋in length/width/height”。","children":[],"note":""},{"title":"作定语时用“a＋数值-单位单数-long/wide/high＋名词”。","children":[],"note":""},{"title":"分数或百分数作主语时，谓语由of后的名词决定。","children":[],"note":""},{"title":"时间、距离、金钱、重量、度量表示整体概念时，谓语通常用单数。","children":[],"note":""}],"note":""},{"title":"数词课堂完整笔记","children":[{"title":"掌握1—19、整十、hundred/thousand/million/billion及确数与概数表达。","children":[],"note":""},{"title":"掌握1st—19th、整十序数词及the/a/物主代词在序数词前的差异。","children":[],"note":""},{"title":"分数、时间、日期、年代、年龄、倍数和长宽高均有固定表达方式。","children":[],"note":""},{"title":"分数/百分数由of后的名词决定；时间、距离、金钱、重量、度量作整体概念时用单数。","children":[],"note":""},{"title":"基数词表示数量，序数词表示顺序；hundred、thousand、million前有具体数字时通常不加-s，表示概数时可用hundreds of。","children":[],"note":""},{"title":"分数：分子用基数词，分母用序数词；分子大于1时分母加-s。分数作主语时谓语依后面的名词单复数确定。","children":[],"note":""},{"title":"时间、日期和年代按课件读法书写；in the 1990s表示20世纪90年代，in his twenties表示他二十多岁。","children":[],"note":""},{"title":"倍数结构：倍数+as+形容词/副词+as；倍数+比较级+than；倍数+the size/length/height of。先判断比较基准。","children":[],"note":""},{"title":"“数词+名词”作定语时名词用单数：a ten-year-old boy，a two-week course；作表语或数量表达时按正常名词规则。","children":[],"note":""}],"note":""},{"title":"数词全方位","children":[{"title":"基数词表示数量、数目。0—10：zero, one, two, three, four, five, six, seven, eight, nine, ten。","children":[],"note":""},{"title":"11—19：eleven, twelve, thirteen, fourteen, fifteen, sixteen, seventeen, eighteen, nineteen；13—19 大多以 -teen 结尾。","children":[],"note":""},{"title":"整十：twenty, thirty, forty, fifty, sixty, seventy, eighty, ninety，以 -ty 结尾。","children":[],"note":""},{"title":"两位数由“整十＋个位数”构成，中间用连字符“-”：twenty-one, thirty-two。","children":[],"note":""},{"title":"三位数及以上从右往左每三位用逗号分隔，依次为 thousand（千）、million（百万）、billion（十亿）；hundred 表“百”。","children":[],"note":""},{"title":"例：345 = three hundred and forty-five；2,234 = two thousand two hundred and thirty-four；一万 ten thousand；十万 one hundred thousand。","children":[],"note":""},{"title":"hundred/thousand/million/billion 表具体数目时不加 -s；表示模糊数目、且后接 of 时加 -s：hundreds of / thousands of / millions of。","children":[],"note":""},{"title":"补充：dozen 一打（12个）；decade 十年。","children":[],"note":""},{"title":"序数词表示顺序，一般以 -th 结尾。","children":[],"note":""},{"title":"特殊：first, second, third。","children":[],"note":""},{"title":"词形提示：eight→eighth（8 去 t）；nine→ninth（9 去 e）；five→fifth、twelve→twelfth（ve→f）；整十 y→ie＋th，如 twenty→twentieth。","children":[],"note":""},{"title":"复合序数词只变个位部分，如 twenty-first。","children":[],"note":""},{"title":"分子在前，分母在后；分子用基数词，分母用序数词；分子大于1时，分母加 -s。","children":[],"note":""},{"title":"2/3 two thirds；3/4 three fourths / three quarters；2/5 two fifths；7/8 seven eighths。","children":[],"note":""},{"title":"1/2 a/one half；1/4 one fourth / a quarter；one second 表“一秒”而非 1/2。","children":[],"note":""},{"title":"百分数：percent，如 20% = twenty percent。","children":[],"note":""},{"title":"小数点：point；小数点后面的内容按数字顺序逐个读：2.345 = two point three four five。","children":[],"note":""},{"title":"直接表示：10:00 = at ten / at ten o’clock；10:20 = at ten twenty；10:30 = at ten thirty。","children":[],"note":""},{"title":"借助介词：to 表“还有多久到几点”（大于30分钟一侧）；past 表“几点过了多少”（小于30分钟一侧）。","children":[],"note":""},{"title":"9:50 = at ten to ten；11:20 = at twenty past eleven。","children":[],"note":""},{"title":"原资料练习：11:21 = at twenty-one past eleven；8:48 = at twelve to nine。","children":[],"note":""},{"title":"中文日期顺序：年/月/日（由大到小）；英语可用“月日年”或“日月年”（由小到大），资料示例 May 23, 2025；April 11, 2026。","children":[],"note":""},{"title":"世纪：in the twenty-first century。","children":[],"note":""},{"title":"年代：in the 1890s；区别具体年份 in 1890。","children":[],"note":""},{"title":"I am 18 years old. = I am at the age of 18.","children":[],"note":""},{"title":"I am an 18-year-old girl.：作定语时 year 用单数并用连字符。","children":[],"note":""},{"title":"in one’s＋整十复数表示“在某人几十岁时”：in my twenties / in his thirties / in Li Hua’s forties。","children":[],"note":""},{"title":"结构：基数词＋单位词＋形容词（high/long/wide等）。","children":[],"note":""},{"title":"ten meters long；twenty feet wide；eight inches high。","children":[],"note":""}],"note":""}],"note":""},{"title":"1.4 形容词与副词","children":[{"title":"形容词与副词","children":[{"title":"形容词常修饰名词、作表语或宾补；副词常修饰动词、形容词、副词或全句。","children":[],"note":""},{"title":"enough：形容词或副词在前，名词通常在后。something important：不定代词后的形容词后置。","children":[],"note":""},{"title":"as…as、倍数＋as…as、the more…the better、one of the＋最高级＋复数名词。注意 hard/hardly、late/lately。","children":[],"note":""}],"note":""},{"title":"形容词与副词课堂笔记（手写）","children":[{"title":"形容词与副词的基本位置","children":[],"note":""},{"title":"比较级和最高级构成","children":[],"note":""},{"title":"副词词形与特殊变化","children":[],"note":""},{"title":"enough与too的结构","children":[],"note":""},{"title":"形容词顺序和复合形容词","children":[],"note":""}],"note":""},{"title":"形容词、副词（上）全方位","children":[{"title":"形容词（adj.）修饰名词、代词，表示人或物的特征、状态、属性等。","children":[],"note":""},{"title":"例：Chongqing is a beautiful city.；Li Hua is a diligent/hard-working student.","children":[],"note":""},{"title":"形容词修饰复合不定代词时要后置：something important；anything interesting。","children":[],"note":""},{"title":"-ed 形容人的心理感受，“感到……的”；-ing 形容物，“令人……的”。","children":[],"note":""},{"title":"excited/exciting；interested/interesting；surprised/surprising；confused/confusing；disappointed/disappointing；embarrassed/embarrassing；bored/boring；tired/tiring。","children":[],"note":""},{"title":"常见搭配：be interested in...；be surprised at...；be tired of...。","children":[],"note":""},{"title":"副词修饰动词、形容词、副词或整个句子，表示程度、方式、时间、地点等。","children":[],"note":""},{"title":"口诀：形修名，副修动。","children":[],"note":""},{"title":"例：He runs very quickly/fast.；I like the movie very much.；I really like the movie.；She speaks very slowly.；We often go swimming.","children":[],"note":""},{"title":"时间副词：now, late, early, then, yesterday, tomorrow 等。","children":[],"note":""},{"title":"频度副词：always, often, usually, sometimes, seldom, never 等；频度副词放在实义动词之前，或助动词/be之后。","children":[],"note":""},{"title":"地点副词：here, there, home, abroad；方向副词：away, back, in, out。","children":[],"note":""},{"title":"方式副词：quickly, slowly, bravely, carefully, happily 等，多以 -ly 结尾；方式副词常放在实义动词之后。","children":[],"note":""},{"title":"部分 -ly 结尾仍是形容词：friendly, lovely, likely, lonely, deadly, timely, daily, weekly, monthly, yearly 等。","children":[],"note":""},{"title":"程度副词：very, badly, greatly, extremely, too, so, slightly, almost 等。","children":[],"note":""},{"title":"否定副词：hardly, never, seldom；疑问副词：when, where, why, how；关系/连接副词用于从句。","children":[],"note":""},{"title":"enough 作形容词修饰名词时放名词前：enough money / enough food。","children":[],"note":""},{"title":"enough 作副词修饰形容词、副词时放后面：fast enough / interesting enough / big enough。","children":[],"note":""},{"title":"so 为副词，修饰形容词、副词：so＋adj./adv.；You are so cute. / He runs so fast.","children":[],"note":""},{"title":"so＋adj.＋a/an＋n.：You are so cute a girl.","children":[],"note":""},{"title":"so＋many/much/little/few＋名词：I have so much money.","children":[],"note":""},{"title":"such 为形容词，修饰名词：such＋a/an＋(adj.)＋n.；You are such a cute girl.","children":[],"note":""},{"title":"such＋adj.＋复数名词/不可数名词：He made such rapid progress. / They are such cute girls.","children":[],"note":""},{"title":"判断提示：看到后面有复数名词或不可数名词，资料提示优先考虑 such。","children":[],"note":""},{"title":"This is such an interesting book. = This is so interesting a book.","children":[],"note":""},{"title":"原级、比较级（两者）、最高级（三者及以上）。","children":[],"note":""},{"title":"规则变化：一般加 -er/-est；以不发音 e 结尾加 -r/-st；辅音字母＋y：y→i＋er/est；重读闭音节末尾辅音双写再加 -er/-est；较长词通常 more/most。","children":[],"note":""},{"title":"例：small→smaller→the smallest；large→larger→the largest；lucky→luckier→the luckiest；big→bigger→the biggest；important→more important→the most important。","children":[],"note":""},{"title":"不规则：good/well→better→the best；bad/badly→worse→the worst；many/much→more→the most；little→less→the least；old→older/elder→oldest/eldest；far→farther/further→farthest/furthest。","children":[],"note":""}],"note":""},{"title":"形容词、副词（下）全方位","children":[{"title":"as...as 表“和……一样”，第一个 as 是副词，第二个 as 是连词；中间用 adj./adv. 原级。","children":[],"note":""},{"title":"You are as tall as me.；This room is as big as that one.","children":[],"note":""},{"title":"否定：not as/so...as... 表“不如……”，只有在否定句中，第一个 as 可替换为 so。","children":[],"note":""},{"title":"You aren’t as/so tall as me.；This room isn’t as/so big as that one.","children":[],"note":""},{"title":"as...as possible / as soon as possible：尽可能…… / 尽快；Please come back as soon as possible.；She runs as fast as possible to catch the thief.","children":[],"note":""},{"title":"as soon as：一……就……；I will call you as soon as I arrive.","children":[],"note":""},{"title":"as long as：只要；I can lend you money as long as you return it on time.","children":[],"note":""},{"title":"as well as：和……一起、一样；Tom, as well as his friends, likes playing basketball.","children":[],"note":""},{"title":"as well：也；He likes swimming, and I like it as well.","children":[],"note":""},{"title":"as early as：早在……；as high as：（数值）高达……。","children":[],"note":""},{"title":"基本结构：比较级＋than。例：This bag is heavier than that one.","children":[],"note":""},{"title":"比较级前一般不加 the；但在“of the two”结构中，比较级前加 the：Of the two cats, I prefer the fatter one.","children":[],"note":""},{"title":"可修饰比较级的词：a little, a bit, much, a great deal, even, still, rather, far 等。","children":[],"note":""},{"title":"原资料提醒：too / very / quite / extremely 等“极其”类程度词不能修饰比较级，后面要跟原级。","children":[],"note":""},{"title":"“越来越……”：比较级 and 比较级；多音节词用 more and more＋adj./adv.。例 taller and taller；fatter and fatter；more and more popular。","children":[],"note":""},{"title":"“越……就越……”：The＋比较级＋主语＋谓语，the＋比较级＋主语＋谓语。例 The more you eat, the fatter you are.；The harder you study, the luckier you are.","children":[],"note":""},{"title":"做题提示：the＋比较级 成对出现。","children":[],"note":""},{"title":"be superior to：比……更高级；be inferior to：比……更低级。","children":[],"note":""},{"title":"the＋最高级；副词最高级前的 the 可以省略。例 He is the tallest boy in our class.；He did his homework most carefully.","children":[],"note":""},{"title":"one of＋the＋最高级＋复数名词：最……之一。例 Hongya Cave is one of the most famous tourist attractions/places of interest in Chongqing.","children":[],"note":""},{"title":"the＋序数词＋最高级：第几……。例 The Yangtze River is the third longest river in the world.","children":[],"note":""},{"title":"比较级表示最高级：比较级＋than＋any other＋名词单数；或 比较级＋than＋the other＋名词复数。","children":[],"note":""},{"title":"倍数：once / twice / three times / four times / five times...；做题提示：倍数放在前面。","children":[],"note":""},{"title":"结构1：A＋谓语动词＋倍数＋as...as＋B。例 This room is twice as big as that one.","children":[],"note":""},{"title":"结构2：A＋谓语动词＋倍数＋比较级＋than＋B。例 This room is twice bigger than that one.","children":[],"note":""},{"title":"结构3：A＋谓语动词＋倍数＋the＋名词（size/length/width/weight...）＋of＋B。例 This room is twice the size of that one.","children":[],"note":""},{"title":"2016：run ___ $2,000 → as high as。","children":[],"note":""},{"title":"2021：paid ___ for it → twice as much。","children":[],"note":""},{"title":"2019：stadium will be ___ the one destroyed → twice as big as。","children":[],"note":""},{"title":"2017：bridge measures ___ that one → twice as long as。","children":[],"note":""},{"title":"2015：costs almost three times ___ → as much。","children":[],"note":""}],"note":""}],"note":""},{"title":"1.5 介词与连词","children":[{"title":"介词与连词","children":[{"title":"时间常用 at 点、on 日、in 较长时间段；since 接起点，for 接时长。","children":[],"note":""},{"title":"介词后接名词、宾格代词或 doing。look forward to doing 中的 to 是介词。","children":[],"note":""},{"title":"because / although 接从句；because of / despite 接名词等。并列连词连接同层成分，留意平行结构。","children":[],"note":""}],"note":""},{"title":"介词与介词短语课堂笔记（手写）","children":[{"title":"in、on、at的时间和地点用法","children":[],"note":""},{"title":"by、for、with等常用介词","children":[],"note":""},{"title":"during、over、before、after等时间介词","children":[],"note":""},{"title":"across、through、past等运动介词","children":[],"note":""},{"title":"方位介词与固定短语","children":[],"note":""},{"title":"原因、让步和排除关系表达","children":[],"note":""}],"note":""},{"title":"介词","children":[{"title":"介词 preposition（prep.）又叫前置词，通常放在名词或相当于名词的结构前面，补充时间、地点、方位、方式、原因等信息，并与后面的成分构成介词短语。","children":[],"note":""},{"title":"介词后接人称代词时用宾格：I am afraid of him.；介词后接动词时用 doing：I am afraid of swimming.","children":[],"note":""},{"title":"介词短语可作表语、定语、状语、宾语补足语等：My book is on the desk. / The house by the lake is very expensive. / We will meet at 2 p.m. / She found the cat on the roof.","children":[],"note":""},{"title":"at＋具体时刻：at 10 o’clock；at noon；at daybreak/dawn；at midnight；at the moment / at present。","children":[],"note":""},{"title":"in＋年份、月份、季节、上午/下午/晚上：in 2025；in June；in summer；in the morning/afternoon/evening。","children":[],"note":""},{"title":"on＋具体某一天、星期、有修饰语的某一天的上午/下午/晚上：on June 5, 2025；on Thursday；on a rainy evening。","children":[],"note":""},{"title":"before：在……之前。by：在……之前、截止到……；原资料提示 by＋时间常和完成时态搭配。","children":[],"note":""},{"title":"after＋时间点/具体动作：after 5 p.m. / after Christmas / after dinner。in＋时间段表示“……之后”，常用于将来时：in two hours。","children":[],"note":""},{"title":"for＋时间段；since＋过去的时间点，原资料均放在完成时语境中：We have studied English for one month. / ... since last month.","children":[],"note":""},{"title":"during：在……期间，如 during the movie / during my college years。","children":[],"note":""},{"title":"from...to...：从……到……，可用于时间、地点、数值：from 9 a.m. to 9 p.m.；from the mountains to the sea；from $10 to $100。","children":[],"note":""},{"title":"within：在……以内，可接时间、地点、数值；固定搭配 within one’s reach（力所能及）、within sight（在视线范围以内）。","children":[],"note":""},{"title":"until/till：直到……；not...until...：直到……才……。","children":[],"note":""},{"title":"in＋大地点：in China / in Chongqing；at＋小地点：at the airport / at school / at the bus stop。","children":[],"note":""},{"title":"on 表示在某物表面或某层/场所：on the second floor / on the playground / on the street / on the left/right。","children":[],"note":""},{"title":"表示方位关系：in 表示包含关系；on 表示接壤；to 表示隔海相望或不接壤。例：Chongqing is in the southwest of China. / Russia is on the north of China. / Japan is to the east of China.","children":[],"note":""},{"title":"in：在……里面；on：在……上面且有接触；beneath：在……下面且强调较近/有接触语境。","children":[],"note":""},{"title":"over：在……之上，常强调垂直覆盖或越过；under：在……之下，常强调垂直关系。","children":[],"note":""},{"title":"above / below：在……之上/之下，不强调垂直接触，也可用于温度、海拔、标准、水平、分数：above/below 35℃；above 4,000 meters；above 90 points。","children":[],"note":""},{"title":"by / beside：在……旁边；near：在……附近；next to：紧挨着。","children":[],"note":""},{"title":"through：穿过内部（如 through a tunnel / through the forest）；across：横穿表面（across the street）；past：经过；over：越过；along：沿着。","children":[],"note":""},{"title":"between：在两者之间；among：在三者及以上之间/当中。","children":[],"note":""},{"title":"原资料例：The keys are on the table. / The village is between the forest and the river. / The sun rises in the east and sets in the west. / The boat floated along the river.","children":[],"note":""},{"title":"by：通过；常见 by＋名词、by＋doing、by＋交通工具：by hard work / by working hard / by bus, car, train, plane, bike。","children":[],"note":""},{"title":"with＋具体工具或身体部位：write with pens；break the window with a stone；point with his finger。","children":[],"note":""},{"title":"in＋材料、语言、衣物颜色：in black ink；communicate in English/Chinese；the girl in red。","children":[],"note":""},{"title":"on＋电子设备/媒介：on radio；on the internet。","children":[],"note":""},{"title":"through＋方式、经历、过程；via＋媒介或经由：through online courses / watching movies；via satellite。","children":[],"note":""},{"title":"for：因为、为了；也见 praise sb. for sth. 表示因某事表扬某人。","children":[],"note":""},{"title":"thanks to：多亏了、由于；原资料同时列出 because of / owing to / due to / result from 等原因表达。","children":[],"note":""},{"title":"例：Thanks to your help, I passed the exam.","children":[],"note":""},{"title":"except：除了……以外，强调排除同类事物；except 一般不放句首。例 He eats everything except fish.","children":[],"note":""},{"title":"besides：除了……还有，表示累加；注意和 beside“在……旁边”区分。","children":[],"note":""},{"title":"except for：除了某个不同类的细节，常用于整体说明后的局部补充：His composition is good except for some spelling mistakes.","children":[],"note":""},{"title":"but 与复合不定代词搭配可表示“只有”：nothing but / nobody but。","children":[],"note":""},{"title":"固定结构：have nothing to do but do sth.；have no choice but to do sth.","children":[],"note":""},{"title":"at：以……速度、价格，如 at a high/low/reasonable price；at 900 kilometers per hour。","children":[],"note":""},{"title":"for：用……作为交换，如 sold his car for 500 dollars。","children":[],"note":""},{"title":"by：按……计算，如 sold by weight。","children":[],"note":""},{"title":"原资料提示：for＋具体金额；at＋price。","children":[],"note":""},{"title":"despite：尽管、虽然；in spite of：尽管、虽然；with all：虽然、尽管。三者后接名词性成分。","children":[],"note":""},{"title":"区别 although / though：although / though 是连词，后接句子。例 Despite the rain, we went hiking. / Although it rained, we went hiking.","children":[],"note":""},{"title":"反抗、与……对抗；违反、违背；反对：rise up against；play against；against the law；against one’s will；be against the plan。","children":[],"note":""},{"title":"挨着、靠着：against the wall。","children":[],"note":""},{"title":"不利于：The evidence/proof is against him.","children":[],"note":""},{"title":"预防、防备：take medicine against the cold。","children":[],"note":""},{"title":"时间题示例：June 7 的 morning 前用 on；Sunday morning 前用 on；training period 前用 during。","children":[],"note":""},{"title":"方位题示例：among the top five；go along Center Street；help him across the street；Diaoyu Island is to the southwest of Japan。","children":[],"note":""},{"title":"方式题示例：by bike；on the radio；by hard work；via satellite。","children":[],"note":""},{"title":"排除题示例：what I have read... → except；nice ___ its service → except for；Nobody ___ Jack... → but；___ his wife, his daughter... → Besides。","children":[],"note":""},{"title":"against 真题：people pushing ___ one another in the subway → against。","children":[],"note":""},{"title":"时间：at具体时刻，on具体某天，in较长时间段；during接名词，while接从句；for表示持续时长，since表示起点。","children":[],"note":""},{"title":"地点：at强调点，in强调范围内部，on强调表面；between用于两者，among用于三者及以上。","children":[],"note":""},{"title":"by表示截止时间或方式，until表示持续到某时；by the time后接从句时主句常用完成时。","children":[],"note":""},{"title":"介词后接名词、代词宾格、动名词或名词性从句，不能直接接动词原形；固定搭配必须整体记忆。","children":[],"note":""},{"title":"短语动词中的介词会改变意义，如look at、look for、look after；翻译先看动词与介词的搭配，不要逐字替换。","children":[],"note":""}],"note":""},{"title":"介词课堂完整笔记","children":[{"title":"课堂定义：介词（preposition）是虚词，本身通常不能独立充当句子成分；放在名词、代词、动名词等前面，和后面的成分构成介词短语。","children":[],"note":""},{"title":"介词短语在句中可作定语、状语、表语、宾语补足语等；课堂最后用 After school is my free time. / Everything is under control. / The man with gray hair is... / I found him in the room. 等句子辨认介词短语。","children":[],"note":""},{"title":"课堂主要从“方位介词、时间介词、方式介词、其他高频介词搭配”四块展开。","children":[],"note":""},{"title":"in：空间内部；on：物体表面且有接触；at：确定的某处、具体点位；to：朝/向，表示不在内部、不在表面，通常不接壤。","children":[],"note":""},{"title":"地区关系例：Chongqing is located in the southwest of China；... on the east of Sichuan；... to the west of Taiwan。","children":[],"note":""},{"title":"地点层级：at 常配具体小地点，如 airport / station / bus stop / home / school；in 可配较大的场所或地区，如 cinema / museum / supermarket / park 等课堂例子。","children":[],"note":""},{"title":"in the tree：外来的东西在树上，如鸟停在树枝间。","children":[],"note":""},{"title":"on the tree：树本身长出来的东西在树上，如 apples on the tree。","children":[],"note":""},{"title":"on：在……上面并有接触；over：在……正上方，常带垂直覆盖/越过意味；above：在……上方，不强调垂直。","children":[],"note":""},{"title":"under：在……正下方；below：在……下方，不强调垂直。课堂例句包括 lamp hangs over the table / plane flies above the clouds / picture is above the sofa / ball rolled under the chair / temperature is below zero 等。","children":[],"note":""},{"title":"in front of：在某物外部的前面；in the front of：在某物内部的前部。","children":[],"note":""},{"title":"behind：在……后面；at the back of：在……内部后部/后面位置。课堂用 car / classroom / door 等例句辨析。","children":[],"note":""},{"title":"near：在……附近，距离概念较宽；by / beside：在……旁边；next to：紧挨着、相邻。","children":[],"note":""},{"title":"课堂例句包含 He lives near the park. / She is standing by/beside the window. / The shop is next to our school.","children":[],"note":""},{"title":"across：横穿表面；through：从内部穿过；past：从……旁边经过。课堂板书提醒 across the street/road，through a tunnel/forest，walk past...。","children":[],"note":""},{"title":"between：两者之间；among：三者及以上之间/群体当中。课堂对比 between...and... 与 among students/friends。","children":[],"note":""},{"title":"课堂继续涉及 opposite（在……对面）、against（靠着/反对/违反等）、along（沿着）、around（围绕/在周围）、at（具体位置）等高频方位表达。","children":[],"note":""},{"title":"重点是根据“内部/表面/点位、是否接触、是否穿过内部、两者还是多者”等空间关系选介词。","children":[],"note":""},{"title":"in：较长时间，如年、月、季节、世纪，以及 morning/afternoon/evening 等；on：具体某一天、日期、星期以及具体某天的早中晚；at：具体时刻或特殊时间点。","children":[],"note":""},{"title":"课堂示例包括 in 2026 / in May / in spring；on Monday / on May 4；at six o’clock / at noon / at sunset / dawn 等。","children":[],"note":""},{"title":"for＋时间段；since＋过去时间点/起点，课堂将其与完成时态结合讲解。","children":[],"note":""},{"title":"例：have lived here for 30 years；have lived here since 30 years ago / since 1996（以课堂板书的“段 vs 点”思路区分）。","children":[],"note":""},{"title":"in＋时间段可表示从现在起多久之后，常与将来时搭配；after 表示某一时间点/事件之后。","children":[],"note":""},{"title":"during 强调在某段期间；over 可表示在一段期间内，课堂例句有 during the meeting / over the meeting、over the holiday 等，并结合时态判断。","children":[],"note":""},{"title":"before：在……之前；after：在……之后；from：从……起，常进入 from...to... 结构。","children":[],"note":""},{"title":"within：在……之内，强调时间上不超过一个范围。","children":[],"note":""},{"title":"by：截止到某时间点，课堂重点提示常与完成时态结合；by the end of... 为常见结构。","children":[],"note":""},{"title":"in＋语言/材料/声音/笔墨颜色，也可表示抽象方式：in English / in ink / in red / in this way。","children":[],"note":""},{"title":"with＋具体工具、身体部位：write with a pen / see with your eyes。","children":[],"note":""},{"title":"through＋人、渠道、过程：through hard work / through practice / through friends。","children":[],"note":""},{"title":"by＋交通工具/方式手段，也常用 by＋doing：by bus / by bike / by plane / make progress by practicing。","children":[],"note":""},{"title":"on＋电子媒介/通讯设备：on the internet / on the radio。","children":[],"note":""},{"title":"besides：除了……还……，表示包含后的增加；except：除了……，表示排除同类；except for：整体肯定后排除不同类的小细节。","children":[],"note":""},{"title":"apart from 依语境可相当于 besides 或 except；except that 后接从句；but 在 nobody/nothing 等否定不定代词后可表示“除了/只有”。","children":[],"note":""},{"title":"课堂将这些词放在同一页做排除关系辨析，并用具体句子判断“加法”还是“减法”。","children":[],"note":""},{"title":"for：可表示目的、对象、交换/价格等；from：表示来源、起点、分离；with：除工具外还可表示伴随、具有、带有某种特征。","children":[],"note":""},{"title":"课堂用 punished/rewarded for、suffer from、with experience 等搭配说明不要只记一个中文意思，要结合动词固定搭配。","children":[],"note":""},{"title":"这些结构都可表示原因；because of 最常用；due to / owing to / on account of 正式程度和使用位置有所不同；thanks to 往往带“多亏了”的意味。","children":[],"note":""},{"title":"课堂通过句子填空辨析这些原因短语，强调后面接名词性成分而不是完整谓语句。","children":[],"note":""},{"title":"about / on / concerning / regarding 都可表示“关于”。课堂将 about 与 on 的语气/正式程度、以及 concerning / regarding 的书面用法放在一起比较。","children":[],"note":""},{"title":"例句围绕 lecture/report/article/policy 等名词展开，做题时重点看固定搭配和语境正式度。","children":[],"note":""},{"title":"despite 与 in spite of 都表示“尽管、虽然”，后接名词性成分；不能直接按 although/though 的连词结构去接完整句子。","children":[],"note":""},{"title":"课堂用 despite the rain / in spite of... 与 although/though＋句子对照。","children":[],"note":""},{"title":"课堂补充大量固定介词短语，重点不是逐字翻译，而是整体记搭配。截图中包括 in＋状态/衣着/语言类短语，on＋活动/状态类短语，at＋时间/地点/状态类短语，under＋控制/压力/讨论等结构。","children":[],"note":""},{"title":"by 的补充用法包括“在……旁边/经过、按……计算、在……之前、通过某种方式”等，需根据后接名词判断含义。","children":[],"note":""},{"title":"课堂末尾句子辨认：After school is my free time. / Everything is under control. / The man with gray hair is... / I found him in the room. / He will leave after sunrise.","children":[],"note":""}],"note":""},{"title":"连词｜完整课堂笔记","children":[{"title":"并列连词连接语法地位相同的单词、短语或分句，连接的成分通常具有相同的语法结构和句法功能。","children":[],"note":""},{"title":"资料例：coffee and tea；tall but thin；sing and dance；slowly but steadily；in London or in Paris；go to school and do homework；my parents and your friends；I came, but she left.","children":[],"note":""},{"title":"Neither you nor I am wrong. 展示 neither ... nor ... 连接并列主语。","children":[],"note":""},{"title":"并列 / 递进：and；both ... and ...；not only ... but also ...；neither ... nor ...。","children":[],"note":""},{"title":"选择：or；either ... or ...；not ... but ...。例 You can pay by cash or by credit card.；They came not by car but on foot.","children":[],"note":""},{"title":"资料用条件句改写说明：Work hard, and you will succeed. 对应 If you work hard, you will succeed.","children":[],"note":""},{"title":"Hurry up, or you will be late. 对应 If you don’t hurry up, you will be late.","children":[],"note":""},{"title":"and 连接时强调前项做到后出现的结果；or 连接时强调不按前项做会出现的后果。","children":[],"note":""},{"title":"资料把 there be、or、either ... or ...、neither ... nor ...、not ... but ...、not only ... but also ... 放在“就近原则”中。","children":[],"note":""},{"title":"Neither the students nor the teacher knows it.：谓语跟较近的 teacher 一致。","children":[],"note":""},{"title":"Either his parents or he is right.：谓语跟较近的 he 一致。","children":[],"note":""},{"title":"Both my girlfriend and Jack like playing games.：both ... and ... 连接主语时按复数处理。","children":[],"note":""},{"title":"当主语后接 with / together with / along with / as well as / rather than / except / but / besides / including 等附加成分时，谓语由主要主语决定。","children":[],"note":""},{"title":"The man rather than the children is responsible for this mistake.","children":[],"note":""},{"title":"The writer along with his works is popular among young people.","children":[],"note":""},{"title":"转折 / 对比：but、while、yet、whereas。例 I wanted to call you, but I forgot your number.；He studied very little, yet he passed.；I am tall while my brother is short.","children":[],"note":""},{"title":"因果：for、so。例 It rained last night, so the streets are wet.；The streets are wet, for it rained last night.","children":[],"note":""},{"title":"课堂句子分析：The Internet provides useful information and convenient communication ways.；Online information is abundant, so we need to learn to tell right from wrong.；The plan is simple in theory but difficult to carry out in practice.","children":[],"note":""},{"title":"资料列出 that、if、whether 可引导名词性从句。","children":[],"note":""},{"title":"例：Whether we will go camping depends on weather.；He ignored the fact that he was wrong.","children":[],"note":""},{"title":"时间：when, while, as, before, after, since, until, till, as soon as, once, whenever。","children":[],"note":""},{"title":"原因：because, since, as, now that, seeing that, considering that。","children":[],"note":""},{"title":"条件：if, unless, as long as, so long as, provided (that), providing (that), on condition (that), in case。","children":[],"note":""},{"title":"让步：although, though, as, even if, even though, while。","children":[],"note":""},{"title":"目的：so that, in order that, lest, for fear that, in case。","children":[],"note":""},{"title":"结果：so ... that, such ... that, so that。","children":[],"note":""},{"title":"比较：than, as ... as, not so / as ... as。","children":[],"note":""},{"title":"方式：as, as if, as though, the way。","children":[],"note":""},{"title":"地点：where, wherever, everywhere。","children":[],"note":""},{"title":"资料例：You will succeed as long as you work hard.；Once you start, you should never give up.","children":[],"note":""},{"title":"课堂截图中答案标注清楚的7道连词 / 主谓一致题已拆入英语题目。","children":[],"note":""},{"title":"蓝色森林复习卡片与课堂截图出现相同知识点时，不重复建同一笔记，只在这一篇完整笔记中同时保留两份来源和原图。","children":[],"note":""}],"note":""}],"note":""},{"title":"1.6 动词","children":[{"title":"动词与情态动词","children":[{"title":"动词先分实义、系、助、情态，再看及物性和句子位置。","children":[],"note":""},{"title":"常见情态动词后接动词原形。mustn’t 表禁止，needn’t 表不必。","children":[],"note":""},{"title":"搭配按结构记：want sb. to do sth.、enjoy doing、make sb. do；注意 stop doing 与 stop to do。","children":[],"note":""}],"note":""},{"title":"动词后接 to do 或 doing","children":[{"title":"want / decide / hope + to do。","children":[],"note":""},{"title":"enjoy / avoid / finish + doing。","children":[],"note":""},{"title":"allow sb. to do sth. 表示允许某人做某事。","children":[],"note":""},{"title":"stop doing 表示停止正在做的事，stop to do 表示停下手头的事去做另一件事。","children":[],"note":""},{"title":"remember doing 回忆做过，remember to do 记得去做。","children":[],"note":""}],"note":""}],"note":""}],"note":"先找谓语与句子主干 → 看空格的词性和位置 → 核对搭配"},{"title":"计算机 01 · 计算机基础知识","children":[{"title":"1.1 计算机文化基础","children":[{"title":"计算机文化基础","children":[{"title":"人物：图灵与可计算性；冯·诺依曼与存储程序；巴贝奇与分析机设计。","children":[],"note":""},{"title":"发展按主要元件区分：电子管、晶体管、集成电路、大规模及超大规模集成电路。","children":[],"note":""},{"title":"分类、特点与应用分开记。常考科学计算、数据处理、过程控制及 CAD、CAM、CAI。","children":[],"note":""}],"note":""},{"title":"冯·诺依曼","children":[{"title":"冯·诺依曼被称为“计算机之父”。","children":[],"note":""},{"title":"冯·诺依曼计算机的核心原理是“存储程序和程序控制”。","children":[],"note":""},{"title":"计算机硬件由运算器、控制器、存储器、输入设备和输出设备五部分组成。","children":[],"note":""},{"title":"程序和数据存放在内存中，需要时自动运行。","children":[],"note":""},{"title":"计算机内部采用二进制编码。","children":[],"note":""}],"note":""},{"title":"图灵","children":[{"title":"图灵被称为“人工智能之父”。","children":[],"note":""},{"title":"图灵的主要贡献包括图灵机和图灵测试。","children":[],"note":""},{"title":"图灵测试通过人机对话检验机器是否具有人工智能。","children":[],"note":""},{"title":"计算机界的“诺贝尔奖”称为图灵奖。","children":[],"note":""},{"title":"图灵机由无限长的纸带、读写头、控制规则和状态寄存器组成。","children":[],"note":""}],"note":""},{"title":"巴贝奇","children":[{"title":"1834年，巴贝奇发明的分析机被誉为现代计算机的雏形。","children":[],"note":""}],"note":""},{"title":"香农","children":[{"title":"香农提出了信息熵概念。","children":[],"note":""}],"note":""},{"title":"阿兰·图灵（知识点图）","children":[{"title":"图灵机（TM）是一台假想的机器，不是一台实际的计算机。","children":[],"note":""},{"title":"图灵机由读写头、无限长的纸带、控制规则和状态寄存器组成。","children":[],"note":""},{"title":"图灵机模型奠定了可计算性理论的基础。","children":[],"note":""},{"title":"存在一台通用图灵机（UTM），可以实现所有图灵机的功能。","children":[],"note":""},{"title":"丘奇—图灵论题认为：直觉上可计算的函数都可用图灵机计算，反之亦然。","children":[],"note":""},{"title":"存在不可计算的问题，例如图灵机的停机问题。","children":[],"note":""},{"title":"图灵测试通过人机对话测试计算机是否拥有人类智能。","children":[],"note":""},{"title":"图灵奖被称为计算机领域的诺贝尔奖，是计算机领域的最高荣誉。","children":[],"note":""},{"title":"姚期智教授于2000年获得图灵奖。","children":[],"note":""}],"note":""},{"title":"冯·诺依曼（知识点图）","children":[{"title":"EDVAC是世界上第一台冯·诺依曼机。","children":[],"note":""},{"title":"冯·诺依曼体系结构的核心是存储程序原理。","children":[],"note":""},{"title":"现代计算机仍然采用冯·诺依曼体系结构。","children":[],"note":""}],"note":""},{"title":"计算机的分代","children":[{"title":"世界上第一台电子计算机所采用的逻辑元件是电子管。","children":[],"note":""},{"title":"计算机发展阶段的划分标志为物理器件。","children":[],"note":""},{"title":"使用超大规模集成电路制造的计算机应归属于第四代。","children":[],"note":""},{"title":"1971年，Intel发明了世界上第一款微处理器Intel 4004。","children":[],"note":""}],"note":""},{"title":"ENIAC","children":[{"title":"世界上第一台电子计算机于1946年诞生，它的英文名字叫ENIAC。","children":[],"note":""}],"note":""},{"title":"神威·太湖之光","children":[{"title":"我国目前速度最快的高性能计算机是神威·太湖之光。","children":[],"note":""}],"note":""},{"title":"UNIVAC","children":[{"title":"标志计算机进入商业应用时代的计算机称为UNIVAC。","children":[],"note":""}],"note":""},{"title":"EDVAC","children":[{"title":"世界上第一台“冯机”叫做EDVAC，为现在计算机在体系结构和工作原理上奠定了基础。","children":[],"note":""}],"note":""},{"title":"硬件上的发展","children":[{"title":"我国量子计算机的代表是“九章”系列和“祖冲之”系列。","children":[],"note":""}],"note":""},{"title":"四个化","children":[{"title":"未来计算机的四个发展方向分别是巨型化、微型化、网络化和智能化。","children":[],"note":""}],"note":""},{"title":"按运算速度与性能分类","children":[{"title":"目前生活中应用最广泛的计算机类型是嵌入式计算机。","children":[],"note":""},{"title":"按照性能划分，“银河”计算机属于巨型计算机。","children":[],"note":""},{"title":"图形处理能力和任务并行能力更强的计算机类型是工作站。","children":[],"note":""},{"title":"不是所有的微型机都是个人计算机。","children":[],"note":""}],"note":""},{"title":"按工作原理分类","children":[{"title":"按照工作原理将计算机分为数字计算机、模拟计算机和数模混合计算机。","children":[],"note":""}],"note":""},{"title":"按功能用途分类","children":[{"title":"计算机按功能用途分为专用计算机和通用计算机。","children":[],"note":""}],"note":""},{"title":"字长","children":[{"title":"通常所说的CPU位数就是CPU的字长。","children":[],"note":""},{"title":"字长越长，CPU的数据处理能力通常越强。","children":[],"note":""}],"note":""},{"title":"主频","children":[{"title":"主频是CPU单位时间内产生时钟脉冲的次数。","children":[],"note":""},{"title":"主频常用GHz作为单位。","children":[],"note":""},{"title":"其他条件相同时，主频越高，运算速度通常越快。","children":[],"note":""}],"note":""},{"title":"内存容量","children":[{"title":"内存容量通常指随机存取存储器RAM的容量。","children":[],"note":""},{"title":"内存容量是计算机性能的重要指标之一。","children":[],"note":""}],"note":""},{"title":"可靠性","children":[{"title":"可靠性表示计算机在规定条件和时间内无故障工作的能力。","children":[],"note":""},{"title":"可靠性常用平均无故障时间MTBF衡量。","children":[],"note":""}],"note":""},{"title":"运算速度","children":[{"title":"运算速度可用MIPS表示。","children":[],"note":""},{"title":"MIPS表示每秒执行百万条指令数。","children":[],"note":""}],"note":""},{"title":"机器字","children":[{"title":"机器字由若干二进制位组成。","children":[],"note":""},{"title":"计算机一次能够处理的二进制位数与字长有关。","children":[],"note":""}],"note":""},{"title":"计算机的特点","children":[{"title":"运算速度快。","children":[],"note":""},{"title":"计算精度高。","children":[],"note":""},{"title":"存储容量大。","children":[],"note":""},{"title":"具有逻辑判断能力。","children":[],"note":""},{"title":"自动化程度高。","children":[],"note":""},{"title":"通用性强。","children":[],"note":""}],"note":""},{"title":"自动控制","children":[{"title":"计算机可用于现代工业生产过程的自动控制。","children":[],"note":""},{"title":"自动控制强调实时检测、分析和控制。","children":[],"note":""}],"note":""},{"title":"数据处理","children":[{"title":"数据处理包括数据的收集、存储、分类、统计和加工。","children":[],"note":""},{"title":"办公自动化、财务管理和银行业务常属于数据处理。","children":[],"note":""}],"note":""},{"title":"科学计算","children":[{"title":"科学计算是计算机最早的应用领域。","children":[],"note":""},{"title":"科学计算又称数值计算。","children":[],"note":""}],"note":""},{"title":"计算机辅助工程缩写","children":[{"title":"CAD：计算机辅助设计。","children":[],"note":""},{"title":"CAI：计算机辅助教学。","children":[],"note":""},{"title":"CAM：计算机辅助制造。","children":[],"note":""},{"title":"CAT：计算机辅助测试。","children":[],"note":""},{"title":"CAE：计算机辅助工程。","children":[],"note":""},{"title":"CBE：计算机辅助教育。","children":[],"note":""},{"title":"CIMS：计算机集成制造系统。","children":[],"note":""},{"title":"CAPP：计算机辅助工艺过程设计。","children":[],"note":""}],"note":""},{"title":"01 阿兰·图灵","children":[{"title":"图灵机主要由一条无限长的纸带和一个读写头组成。","children":[],"note":""},{"title":"图灵机是一个数学模型、思维机器，不是一台实际的计算机。","children":[],"note":""},{"title":"图灵机证明了通用计算理论，奠定了可计算性理论的基础。","children":[],"note":""},{"title":"通用图灵机能够解决所有图灵机能够解决的问题。","children":[],"note":""},{"title":"现代计算机的功能不可能超越图灵机。","children":[],"note":""},{"title":"现代计算机能够实现的功能是图灵机功能的子集。","children":[],"note":""},{"title":"只有图灵机能解决的计算问题，实际计算机才能解决。","children":[],"note":""},{"title":"图灵机不可以计算的问题，现代计算机也不能计算。","children":[],"note":""},{"title":"一切直觉上可计算的函数都可用图灵机计算，反之亦然。","children":[],"note":""},{"title":"存在图灵机不能解决的问题，例如停机问题。","children":[],"note":""},{"title":"图灵是计算机科学的奠基人。","children":[],"note":""},{"title":"图灵奖由美国计算机学会（ACM）为纪念图灵而创立，是计算机领域最高奖项。","children":[],"note":""},{"title":"图灵机的所有可能状态数目有限，并存在停机状态。","children":[],"note":""},{"title":"一个问题需要一台图灵机，不同问题需要不同图灵机。","children":[],"note":""},{"title":"图灵机模型影响了读写、算法、程序语言和计算机架构的形成。","children":[],"note":""},{"title":"图灵机思想来自1936年论文《论可计算数及其在判定问题中的应用》。","children":[],"note":""},{"title":"图灵测试来自1950年论文《Computing Machinery and Intelligence》。","children":[],"note":""},{"title":"PDF列出的华人图灵奖获得者为姚期智。","children":[],"note":""}],"note":""},{"title":"02 冯·诺依曼","children":[{"title":"冯·诺依曼是第一台冯·诺依曼机EDVAC的设计者，首次提出“存储程序控制”原理。","children":[],"note":""},{"title":"计算机由运算器、控制器、存储器、输入设备和输出设备五部分组成。","children":[],"note":""},{"title":"程序和数据以同等地位存储在内存中，并按地址访问。","children":[],"note":""},{"title":"计算机按照程序顺序执行。","children":[],"note":""},{"title":"程序和数据以二进制表示。","children":[],"note":""},{"title":"现代计算机的基本结构仍采用冯·诺依曼体系结构，属于冯·诺依曼机。","children":[],"note":""},{"title":"冯·诺依曼被称为计算机之父，奠定了现代计算机理论基础。","children":[],"note":""},{"title":"全名为约翰·冯·诺依曼（John von Neumann）。","children":[],"note":""},{"title":"相关真题年份和教材页码只作查阅。","children":[],"note":""}],"note":""},{"title":"03 著名计算机","children":[{"title":"算筹是古代中国人发明的世界上最早的计算工具。","children":[],"note":""},{"title":"许多人认为算盘是最早的数字计算机，珠算口诀是最早的体系化算法。","children":[],"note":""},{"title":"查尔斯·巴贝奇于1834年发明分析机。","children":[],"note":""},{"title":"分析机被公认为现代通用电子计算机的雏形。","children":[],"note":""},{"title":"ENIAC诞生于1946年2月。","children":[],"note":""},{"title":"ENIAC表明电子计算机时代到来，具有划时代意义。","children":[],"note":""},{"title":"ENIAC面向科学计算，早期计算机主要用于科学计算。","children":[],"note":""},{"title":"ENIAC是非冯·诺依曼机，使用十进制编码，没有存储器，未采用“存储程序原理”。","children":[],"note":""},{"title":"EDVAC是世界上第一台冯·诺依曼机，采用“存储程序控制”的设计思想。","children":[],"note":""},{"title":"UNIVAC-I是世界上第一款批量制造的电子计算机，奠定了计算机工业的基础。","children":[],"note":""},{"title":"我国第一台电子计算机M103诞生于1958年8月1日。","children":[],"note":""},{"title":"我国第一台超级计算机“银河-I”诞生于1983年。","children":[],"note":""},{"title":"“神威·太湖之光”于2016年投入运行，CPU采用拥有自主知识产权的“申威26010”。","children":[],"note":""},{"title":"ENIAC、EDVAC、UNIVAC-I均使用电子管，属于第一代计算机。","children":[],"note":""},{"title":"UNIVAC-I主要面向公众领域的数据处理和商用。","children":[],"note":""},{"title":"“神威·太湖之光”的运算量级和其他曾登顶机型只作了解。","children":[],"note":""},{"title":"算盘珠可承担输入和存储作用，珠算口诀类似控制指令，但算盘无法自动运行。","children":[],"note":""}],"note":""},{"title":"04 发展阶段","children":[{"title":"第一代是电子管时代。","children":[],"note":""},{"title":"第一代软件以机器语言和汇编语言为主。","children":[],"note":""},{"title":"第二代是晶体管时代。","children":[],"note":""},{"title":"第二代出现高级程序设计语言，第一个高级程序设计语言是Fortran。","children":[],"note":""},{"title":"第三代是中小规模集成电路时代。","children":[],"note":""},{"title":"第三代出现操作系统，第一个经典的分时操作系统是Unix（1971年）。","children":[],"note":""},{"title":"第四代是大规模与超大规模集成电路时代。","children":[],"note":""},{"title":"第四代硬件采用大规模与超大规模集成电路，软件出现数据库系统。","children":[],"note":""},{"title":"LSI表示大规模集成电路，VLSI表示超大规模集成电路。","children":[],"note":""},{"title":"1971年Intel 4004微处理器诞生，标志计算机进入第四代。","children":[],"note":""},{"title":"计算机分代的依据是主机部分采用的物理器件不同。","children":[],"note":""},{"title":"目前计算机仍处于第四代，体系结构没有大的突破，仍属于冯·诺依曼机。","children":[],"note":""},{"title":"各代具体起止时间、代表机型以及第五代研究目标只作了解。","children":[],"note":""},{"title":"第一代代表有ENIAC、EDVAC、UNIVAC-I；第三代代表有IBM 360。","children":[],"note":""},{"title":"IC、SSI、MSI等英文缩写和规模分类只作了解。","children":[],"note":""}],"note":""},{"title":"05 计算机的特点","children":[{"title":"计算机运算速度快、精度高。","children":[],"note":""},{"title":"计算机具备存储能力。","children":[],"note":""},{"title":"计算机具备逻辑判断能力。","children":[],"note":""},{"title":"计算机具备自动运行和自动控制的能力。","children":[],"note":""},{"title":"存储程序控制原理是计算机区别于其他计算工具的本质。","children":[],"note":""},{"title":"计算机具备人机交互功能。","children":[],"note":""},{"title":"计算机概念、CPU、存储设备、布尔代数、门电路和用户界面的说明只作理解。","children":[],"note":""},{"title":"逻辑判断能力是计算机智能化的基本条件。","children":[],"note":""}],"note":""},{"title":"06 计算机的分类","children":[{"title":"计算机按用途分为通用机和专用机。","children":[],"note":""},{"title":"高性能计算机中的巨型机即超级计算机，主要用于科研和军事。","children":[],"note":""},{"title":"服务器是在网络环境中对外提供服务的高性能计算机。","children":[],"note":""},{"title":"工作站是高端的通用微型计算机，性能强于个人计算机。","children":[],"note":""},{"title":"PC是Personal Computer，即个人电脑。","children":[],"note":""},{"title":"微型计算机包括桌面型电脑、笔记本、平板电脑和移动设备。","children":[],"note":""},{"title":"嵌入式计算机是作为信息处理部件嵌入应用系统中的计算机。","children":[],"note":""},{"title":"单片机把运算器、控制器、存储器、输入输出设备和软件系统集成在一个芯片上，是嵌入式系统的基础。","children":[],"note":""},{"title":"嵌入式计算机软件与硬件一体化，应用最广泛，数量超过PC。","children":[],"note":""},{"title":"通用机与专用机的具体能力差异只作理解。","children":[],"note":""},{"title":"大中小型机、服务器软件类型和工作站图形处理优势的补充说明只作了解。","children":[],"note":""},{"title":"个人电脑的历史、家庭办公用途和兼容性只作了解。","children":[],"note":""}],"note":""},{"title":"07 计算机的应用","children":[{"title":"科学计算又称数值计算，科研和军事是其主要领域，也是计算机最早的应用领域。","children":[],"note":""},{"title":"数据处理又称非数值计算或事务处理，主要用于商业领域。","children":[],"note":""},{"title":"过程控制是对压力、液位、流量、温度等参数进行采集与处理的技术。","children":[],"note":""},{"title":"过程控制主要采用实时操作系统，是自动化技术的重要组成部分。","children":[],"note":""},{"title":"CAD是Computer Aided Design，即计算机辅助设计。","children":[],"note":""},{"title":"CAI是Computer Aided Instruction，即计算机辅助教学。","children":[],"note":""},{"title":"CBE是Computer Based Education，即计算机辅助教育或计算机化教育。","children":[],"note":""},{"title":"CAM是Computer Aided Manufacturing，即计算机辅助制造。","children":[],"note":""},{"title":"CIMS是Computer Integrated Manufacturing System，即计算机集成制造系统。","children":[],"note":""},{"title":"多媒体包含文本、音频、视频、动画等多种媒体形式。","children":[],"note":""},{"title":"多媒体技术以计算机技术为核心，将现代声像技术和通信技术融为一体。","children":[],"note":""},{"title":"Internet是国际互联网，是全球范围内最大的计算机网络。","children":[],"note":""},{"title":"IoT是Internet of Things，实现物与物、物与人、人与人之间的万物互连。","children":[],"note":""},{"title":"Artificial Intelligence（AI）指用计算机模拟人类智能，实现人工智能的根本途径是机器学习（ML）。","children":[],"note":""},{"title":"2016年AlphaGo击败李世石。","children":[],"note":""},{"title":"2017年AlphaGo击败柯洁。","children":[],"note":""},{"title":"2022年OpenAI发布的ChatGPT已具有初步学术论文撰写功能。","children":[],"note":""},{"title":"科学计算和数据处理的数据量、计算复杂度等完整定义只作理解。","children":[],"note":""},{"title":"过程控制主要应用于工业生产领域。","children":[],"note":""},{"title":"CAL、CBL、CAE、CAT、CMI、CAPP、EDA等PDF中未加粗的辅助工程缩写只作了解。","children":[],"note":""},{"title":"多媒体、网络和人工智能的具体生活应用，以及1997年“深蓝”事件只作了解。","children":[],"note":""}],"note":""},{"title":"08 计算机的未来","children":[{"title":"未来计算机将朝着巨型化、微型化、网络化和智能化的方向发展。","children":[],"note":""},{"title":"光子计算机用光子代替电子进行计算和存储，具有超强并行能力和超高速运算速度。","children":[],"note":""},{"title":"生物计算机又称分子计算机，采用蛋白质分子构成生物芯片，信息以波的形式传播，存储能力巨大。","children":[],"note":""},{"title":"处理和计算量子信息、运行量子算法的装置称为量子计算机。","children":[],"note":""},{"title":"1993年姚期智证明量子图灵机与量子线路之间存在等价性，为实现量子计算机提供理论基础。","children":[],"note":""},{"title":"我国在量子计算机领域处于世界领先地位。","children":[],"note":""},{"title":"2017年5月，中国科学技术大学潘建伟等人构建出世界上第一台光量子计算机。","children":[],"note":""},{"title":"多核化、多媒体化等另一种表述，以及光存储技术发展只作了解。","children":[],"note":""},{"title":"生物计算机的速度和能耗比较只作了解。","children":[],"note":""},{"title":"量子比特、态叠加、Hilbert空间、量子纠缠、量子并行和可逆计算的详细解释只作了解。","children":[],"note":""},{"title":"1982年费曼、1985年杜斯、2020年“九章”等未加粗时间线只作了解。","children":[],"note":""}],"note":""},{"title":"计算机六大特点","children":[{"title":"计算机具备存储和逻辑判断能力。","children":[],"note":""},{"title":"存储程序控制原理使计算机能够自动运行与自动控制。","children":[],"note":""},{"title":"用户界面实现人机交互。","children":[],"note":""},{"title":"布尔代数和门电路构成计算机逻辑判断的基础。","children":[],"note":""},{"title":"自动运行是计算机区别于一般计算工具的本质特征。","children":[],"note":""}],"note":""},{"title":"按用途和性能分类","children":[{"title":"按用途分为通用机和专用机。","children":[],"note":""},{"title":"按性能分为高性能计算机、服务器、工作站、微型计算机和嵌入式计算机。","children":[],"note":""},{"title":"通用机综合处理能力强；专用机围绕特定任务配置软硬件。","children":[],"note":""},{"title":"服务器面向网络提供服务；工作站是高端通用微型计算机。","children":[],"note":""}],"note":""},{"title":"嵌入式计算机与单片机","children":[{"title":"嵌入式计算机是嵌入应用系统的信息处理部件。","children":[],"note":""},{"title":"单片机把运算器、控制器、存储器、输入输出设备及固化软件集成在一个芯片上。","children":[],"note":""},{"title":"嵌入式系统特点是软硬件一体化、应用广、数量多。","children":[],"note":""},{"title":"传统设备嵌入单片机后可获得计算和智能控制能力。","children":[],"note":""}],"note":""},{"title":"科学计算、数据处理与过程控制","children":[{"title":"科学计算又称数值计算，数据量小但计算复杂。","children":[],"note":""},{"title":"数据处理又称非数值计算或事务处理，数据量大但计算较简单。","children":[],"note":""},{"title":"过程控制采集压力、液位、流量、温度等参数，强调实时性。","children":[],"note":""},{"title":"科学计算最早用于科研和军事；数据处理广泛用于商业和管理系统；过程控制主要用于工业生产。","children":[],"note":""}],"note":""},{"title":"计算机辅助工程缩写总表","children":[{"title":"CAD是计算机辅助设计。","children":[],"note":""},{"title":"CAI是计算机辅助教学。","children":[],"note":""},{"title":"CAM是计算机辅助制造。","children":[],"note":""},{"title":"CIMS是计算机集成制造系统。","children":[],"note":""},{"title":"CAE是计算机辅助工程。","children":[],"note":""},{"title":"Computer Aided/Assisted表示“计算机辅助”，Computer Based表示“基于计算机/计算机化”。","children":[],"note":""}],"note":""},{"title":"多媒体、物联网与人工智能","children":[{"title":"多媒体技术以计算机技术为核心，融合现代声像与通信技术。","children":[],"note":""},{"title":"物联网IoT实现物与物、物与人、人与人的万物互联。","children":[],"note":""},{"title":"人工智能AI是用计算机模拟人类智能，实现人工智能的根本途径是机器学习。","children":[],"note":""},{"title":"典型AI应用包括语音助手、人脸识别、推荐系统、智能家居、无人驾驶和机器人。","children":[],"note":""}],"note":""},{"title":"未来方向与新型计算机","children":[{"title":"未来计算机朝巨型化、微型化、网络化和智能化方向发展。","children":[],"note":""},{"title":"光子计算机用光子代替电子计算和存储。","children":[],"note":""},{"title":"生物计算机又称分子计算机，使用蛋白质分子构成生物芯片。","children":[],"note":""},{"title":"部分资料还列多核化、多媒体化，属于扩展趋势；考试主干仍优先记“四个化”。","children":[],"note":""}],"note":""},{"title":"量子计算核心原理与代表成就","children":[{"title":"量子比特可处于0和1的叠加态。","children":[],"note":""},{"title":"态叠加原理是现代量子计算机模型的核心技术。","children":[],"note":""},{"title":"Hilbert空间用于表达量子系统。","children":[],"note":""},{"title":"量子纠缠中一个粒子的状态会影响另一个粒子且与距离无关。","children":[],"note":""},{"title":"量子并行使量子计算机能同时处理大量状态。","children":[],"note":""},{"title":"1982费曼提出量子通用计算设想；1985杜斯提出量子图灵机；1993姚期智证明量子图灵机与量子线路等价。","children":[],"note":""}],"note":""}],"note":""},{"title":"1.2 进制转换","children":[{"title":"数制与位运算","children":[{"title":"按位权展开：每位数码×基数的对应次幂。整数部分从个位起，小数首位权为 r⁻¹。","children":[],"note":""},{"title":"十进制整数转 r 进制：除 r 取余逆序。小数：乘 r 取整顺序。二进制与八/十六进制按 3/4 位分组。","children":[],"note":""},{"title":"AND 同 1 才 1，OR 有 1 即 1，XOR 不同为 1。计算单位注意 1 B=8 bit；二进制容量换算与十进制频率换算分开。","children":[],"note":""}],"note":""},{"title":"进制与容量自检","children":[{"title":"(1011.01)₂=8+2+1+1/4=11.25。","children":[],"note":""},{"title":"整数分组向左补零，小数分组向右补零。","children":[],"note":""},{"title":"1 KiB=1024 B，1 kB=1000 B。做题按题干给出的单位约定。","children":[],"note":""}],"note":""},{"title":"数制基本概念：基数、数位、权位、数码","children":[{"title":"基数：一种数制所使用的数码个数。","children":[],"note":""},{"title":"数位：数码在数中的位置。","children":[],"note":""},{"title":"位权：某数位代表的权值。","children":[],"note":""},{"title":"数码：数制中使用的基本数字符号。","children":[],"note":""}],"note":""},{"title":"进制的表示方法","children":[{"title":"二进制常用B表示。","children":[],"note":""},{"title":"八进制常用O或Q表示。","children":[],"note":""},{"title":"十进制常用D表示。","children":[],"note":""},{"title":"十六进制常用H表示。","children":[],"note":""}],"note":""},{"title":"计算机采用二进制的原因","children":[{"title":"二进制只有0和1，物理实现简单。","children":[],"note":""},{"title":"二进制运算规则简单。","children":[],"note":""},{"title":"二进制具有较高可靠性。","children":[],"note":""},{"title":"二进制便于进行逻辑运算。","children":[],"note":""}],"note":""},{"title":"二进制加法运算","children":[{"title":"二进制加法的进位规则是逢2进1。","children":[],"note":""},{"title":"0+0=0，0+1=1，1+1=10。","children":[],"note":""}],"note":""},{"title":"二进制减法运算","children":[{"title":"二进制减法的借位规则是借1当2。","children":[],"note":""},{"title":"不够减时向高位借1。","children":[],"note":""}],"note":""},{"title":"与运算","children":[{"title":"与运算规则：同为1得1，其余得0。","children":[],"note":""}],"note":""},{"title":"或运算","children":[{"title":"或运算规则：有1得1，全0得0。","children":[],"note":""}],"note":""},{"title":"异或运算","children":[{"title":"异或运算规则：相同得0，不同得1。","children":[],"note":""}],"note":""},{"title":"非运算","children":[{"title":"非运算规则：0变1，1变0。","children":[],"note":""}],"note":""},{"title":"补0法的原则","children":[{"title":"整数部分不足位数时在左侧补0。","children":[],"note":""},{"title":"小数部分不足位数时在右侧补0。","children":[],"note":""},{"title":"补0不会改变数值大小。","children":[],"note":""}],"note":""},{"title":"十六进制转二进制","children":[{"title":"十六进制每1位对应二进制4位。","children":[],"note":""}],"note":""},{"title":"八进制转二进制","children":[{"title":"八进制每1位对应二进制3位。","children":[],"note":""}],"note":""},{"title":"八进制与十六进制相互转换","children":[{"title":"八进制转十六进制：先转二进制，再按4位分组。","children":[],"note":""},{"title":"十六进制转八进制：先转二进制，再按3位分组。","children":[],"note":""}],"note":""},{"title":"移位运算","children":[{"title":"R进制数左移一位相当于乘R。","children":[],"note":""},{"title":"R进制数右移一位相当于除R。","children":[],"note":""}],"note":""},{"title":"二进制奇偶判断","children":[{"title":"二进制整数最低位为0时是偶数。","children":[],"note":""},{"title":"二进制整数最低位为1时是奇数。","children":[],"note":""}],"note":""},{"title":"R进制转十进制","children":[{"title":"R进制转十进制的方法是按权展开求和。","children":[],"note":""}],"note":""},{"title":"十进制转R进制","children":[{"title":"十进制整数转R进制：除R取余，逆序排列。","children":[],"note":""},{"title":"十进制小数转R进制：乘R取整，顺序排列。","children":[],"note":""}],"note":""}],"note":""},{"title":"1.3 计算机中信息的表示","children":[{"title":"信息表示与编码","children":[{"title":"固定字长下看符号位和数值位。负数补码可用按位取反加一；n 位补码范围 −2ⁿ⁻¹ 至 2ⁿ⁻¹−1。","children":[],"note":""},{"title":"ASCII 标准编码为 7 位，通常存入 1 字节；Unicode 是字符编码体系，UTF-8 是其编码形式之一。","children":[],"note":""},{"title":"汉字编码按用途区分输入码、交换码、机内码、字形码。点阵位图按点数和每点位数计算容量。","children":[],"note":""}],"note":""},{"title":"存储单位换算","children":[{"title":"1Byte等于8bit。","children":[],"note":""},{"title":"1KB=1024B。","children":[],"note":""},{"title":"1MB=1024KB。","children":[],"note":""},{"title":"1GB=1024MB。","children":[],"note":""}],"note":""},{"title":"位（bit）","children":[{"title":"位bit是计算机中最小的数据单位。","children":[],"note":""},{"title":"一个二进制位只能表示0或1。","children":[],"note":""}],"note":""},{"title":"已知补码求原码","children":[{"title":"正数的原码、反码和补码相同。","children":[],"note":""},{"title":"负数由补码求原码：符号位不变，其余位取反加1。","children":[],"note":""}],"note":""},{"title":"数符","children":[{"title":"数符0表示正数。","children":[],"note":""},{"title":"数符1表示负数。","children":[],"note":""}],"note":""},{"title":"求移码","children":[{"title":"移码与补码的数值位相同。","children":[],"note":""},{"title":"补码符号位取反即可得到移码。","children":[],"note":""}],"note":""},{"title":"尾数和阶码","children":[{"title":"浮点数主要由阶码和尾数组成。","children":[],"note":""},{"title":"阶码位数决定表示范围。","children":[],"note":""},{"title":"尾数位数决定表示精度。","children":[],"note":""}],"note":""},{"title":"二进制最多状态数","children":[{"title":"n位二进制数最多表示2^n种状态。","children":[],"note":""},{"title":"n位无符号数最大值为2^n-1。","children":[],"note":""}],"note":""},{"title":"无符号数","children":[{"title":"n位无符号数范围为0～2^n-1。","children":[],"note":""},{"title":"6位无符号数最大值是63。","children":[],"note":""}],"note":""},{"title":"有符号数","children":[{"title":"n位补码有符号数范围为-2^(n-1)～2^(n-1)-1。","children":[],"note":""},{"title":"8位补码范围为-128～127。","children":[],"note":""}],"note":""},{"title":"Unicode","children":[{"title":"Unicode旨在统一世界各种文字的编码。","children":[],"note":""},{"title":"Unicode兼容ASCII。","children":[],"note":""},{"title":"常见编码形式有UTF-8、UTF-16、UTF-32。","children":[],"note":""}],"note":""},{"title":"标准ASCII","children":[{"title":"标准ASCII使用7位编码。","children":[],"note":""},{"title":"标准ASCII可表示128个字符。","children":[],"note":""},{"title":"标准ASCII码值范围为0～127。","children":[],"note":""}],"note":""},{"title":"ASCII码值大小比较","children":[{"title":"ASCII码比较依据字符对应的编码数值。","children":[],"note":""},{"title":"常见顺序：空格＜数字＜大写字母＜小写字母。","children":[],"note":""}],"note":""},{"title":"常见ASCII码值及计算","children":[{"title":"换行LF的ASCII码为10。","children":[],"note":""},{"title":"回车CR的ASCII码为13。","children":[],"note":""},{"title":"空格ASCII码为32。","children":[],"note":""},{"title":"字符0的ASCII码为48。","children":[],"note":""},{"title":"大写A为65，小写a为97。","children":[],"note":""},{"title":"同一字母大小写ASCII码相差32。","children":[],"note":""}],"note":""},{"title":"UTF-8","children":[{"title":"UTF-8是Unicode的一种编码实现。","children":[],"note":""},{"title":"UTF-8采用可变长度编码。","children":[],"note":""}],"note":""},{"title":"扩充ASCII","children":[{"title":"扩充ASCII使用8位编码。","children":[],"note":""},{"title":"扩充ASCII可表示256个字符。","children":[],"note":""},{"title":"扩展区码值通常为128～255。","children":[],"note":""}],"note":""},{"title":"点阵式输出码的计算","children":[{"title":"点阵字形每个点用1bit表示。","children":[],"note":""},{"title":"n×m点阵所需字节数为n×m÷8，不能整除时向上取整。","children":[],"note":""},{"title":"24×24点阵需要72Byte。","children":[],"note":""}],"note":""},{"title":"点阵图和矢量图的区别","children":[{"title":"点阵图由像素组成，放大容易失真。","children":[],"note":""},{"title":"矢量图由数学描述构成，缩放通常不失真。","children":[],"note":""}],"note":""},{"title":"常见汉字字符集","children":[{"title":"GB2312是常见简体中文字符集。","children":[],"note":""},{"title":"BIG5常用于繁体中文。","children":[],"note":""},{"title":"GBK是GB2312的扩展。","children":[],"note":""},{"title":"GB18030覆盖范围更广。","children":[],"note":""}],"note":""},{"title":"机内码","children":[{"title":"汉字在计算机内部存储和处理使用机内码。","children":[],"note":""},{"title":"GB2312中一个汉字机内码通常占2Byte。","children":[],"note":""},{"title":"机内码两个字节的最高位均为1。","children":[],"note":""}],"note":""},{"title":"区位码","children":[{"title":"区位码由区号和位号组成。","children":[],"note":""},{"title":"区位码常用四位十进制表示。","children":[],"note":""},{"title":"前两位为区号，后两位为位号。","children":[],"note":""}],"note":""},{"title":"国标码","children":[{"title":"国标码又称汉字交换码。","children":[],"note":""},{"title":"区位码两个字节分别加20H可得到国标码。","children":[],"note":""}],"note":""},{"title":"区位码、国标码与机内码的计算","children":[{"title":"区位码+2020H=国标码。","children":[],"note":""},{"title":"国标码+8080H=机内码。","children":[],"note":""},{"title":"区位码+A0A0H=机内码。","children":[],"note":""}],"note":""},{"title":"字形码","children":[{"title":"字形码用于汉字显示或打印。","children":[],"note":""},{"title":"字形码常见表示方式有点阵和矢量。","children":[],"note":""}],"note":""},{"title":"区位码、国标码与机内码的范围","children":[{"title":"区位码范围常记为0101H～5E5EH。","children":[],"note":""},{"title":"国标码范围常记为2121H～7E7EH。","children":[],"note":""},{"title":"机内码范围常记为A1A1H～FEFEH。","children":[],"note":""}],"note":""},{"title":"产生乱码的原因","children":[{"title":"保存和读取时使用不同编码可能产生乱码。","children":[],"note":""},{"title":"缺少对应字符集或字库也可能产生乱码。","children":[],"note":""}],"note":""},{"title":"输入码","children":[{"title":"输入码又称外码，用于汉字输入。","children":[],"note":""},{"title":"常见输入码包括音码、形码和音形码。","children":[],"note":""},{"title":"同一汉字可有不同输入码，但对应唯一机内码。","children":[],"note":""}],"note":""}],"note":""},{"title":"1.4 计算机系统组成","children":[{"title":"硬件与性能指标","children":[{"title":"五大组成：运算器、控制器、存储器、输入设备、输出设备。CPU 重点区分运算器与控制器。","children":[],"note":""},{"title":"寄存器、Cache、主存、外存按用途和层级比较；RAM 断电通常丢失数据。","children":[],"note":""},{"title":"主频、字长、存储容量等是不同指标。频率：1 kHz=10³ Hz，1 MHz=10⁶ Hz。","children":[],"note":""}],"note":""},{"title":"软件系统与工作原理","children":[{"title":"系统软件负责管理与支撑，应用软件面向具体任务。区分操作系统、语言处理程序和办公软件。","children":[],"note":""},{"title":"机器语言可由 CPU 直接执行；汇编语言由汇编程序转换；高级语言通常需编译或解释。","children":[],"note":""},{"title":"存储程序与程序控制：程序和数据预先存储，CPU 依次取指、译码、执行；分支可改变顺序。","children":[],"note":""}],"note":""},{"title":"高级语言","children":[{"title":"用高级语言编写的程序称为高级语言源程序。","children":[],"note":""},{"title":"Java是跨平台、采用虚拟机技术的面向对象解释型语言。","children":[],"note":""},{"title":"高级语言可分为面向对象和面向过程。","children":[],"note":""},{"title":"Python是面向对象的解释型语言。","children":[],"note":""}],"note":""},{"title":"汇编语言","children":[{"title":"汇编语言在机器语言基础上增加助记符。","children":[],"note":""},{"title":"助记符在一定程度上改善机器语言难记难读的缺点。","children":[],"note":""},{"title":"汇编语言仍需通过汇编程序转换为机器语言。","children":[],"note":""}],"note":""},{"title":"机器语言","children":[{"title":"机器语言由二进制编码构成。","children":[],"note":""},{"title":"机器语言能够被计算机直接执行。","children":[],"note":""}],"note":""},{"title":"编译程序","children":[{"title":"C语言源程序变为目标程序必须经过编译。","children":[],"note":""},{"title":"编译程序会产生目标程序。","children":[],"note":""}],"note":""},{"title":"系统软件的概念","children":[{"title":"系统软件包括操作系统、程序设计语言、语言处理程序和数据库管理系统。","children":[],"note":""},{"title":"系统软件的核心是操作系统。","children":[],"note":""},{"title":"计算机软件系统分为系统软件和应用软件。","children":[],"note":""},{"title":"程序、数据及相关文档资料统称软件。","children":[],"note":""}],"note":""},{"title":"解释程序","children":[{"title":"编译程序会产生目标程序，解释程序不会产生目标程序。","children":[],"note":""},{"title":"解释方式通常边翻译边执行。","children":[],"note":""}],"note":""}],"note":""},{"title":"1.5 计算思维","children":[{"title":"计算思维","children":[{"title":"把问题转成可描述、可求解的形式，关注抽象、分解、建模、算法与验证。","children":[],"note":""},{"title":"明确输入、输出和约束，再设计步骤，用普通例和边界例检验。","children":[],"note":""},{"title":"做题先辨是在问问题表示、求解步骤，还是实现与优化。不同问题可复用同一求解思路。","children":[],"note":""}],"note":""},{"title":"09 计算思维","children":[{"title":"计算是基于规则的符号串变换。","children":[],"note":""},{"title":"理论思维是推理思维，以推理和演绎为特征，以数学学科为代表。","children":[],"note":""},{"title":"实验思维是实证思维，以观察和总结自然规律为特征，以物理学科为代表。","children":[],"note":""},{"title":"计算思维是构造思维，以设计和构造为特征，以计算机学科为代表。","children":[],"note":""},{"title":"计算思维是运用计算机科学的基础概念进行问题求解、系统设计以及人类行为理解的一系列思维活动。","children":[],"note":""},{"title":"计算思维的本质是抽象和自动化。","children":[],"note":""},{"title":"抽象离不开形式化和数学建模。","children":[],"note":""},{"title":"抽象以后就是自动化，抽象是自动化的前提和基础。","children":[],"note":""},{"title":"计算机通过程序实现自动化，程序的核心是算法。","children":[],"note":""},{"title":"简单问题的自动化通常分为设计算法和编写程序两步。","children":[],"note":""},{"title":"计算思维是概念化，不是程序化。","children":[],"note":""},{"title":"计算思维是思想，不是人造品。","children":[],"note":""},{"title":"计算思维属于人的思维，不是计算机的思维。","children":[],"note":""},{"title":"计算思维可由人执行，也可由计算机执行。","children":[],"note":""},{"title":"计算思维的基本问题有可计算性、计算复杂性和图灵测试。","children":[],"note":""},{"title":"可计算问题可以由计算机在有限步骤内解决。","children":[],"note":""},{"title":"丘奇-图灵论题认为一切直觉上可计算的函数都可用图灵机计算，反之亦然。","children":[],"note":""},{"title":"并不是所有问题都可计算。","children":[],"note":""},{"title":"计算复杂性的度量标准有时间复杂性和空间复杂性。","children":[],"note":""},{"title":"图灵测试指出了人工智能和机器应达到的智能标准，目前已不能全方位评估人工智能。","children":[],"note":""},{"title":"计算思维的核心是计算思维方法。","children":[],"note":""},{"title":"计算思维方法分为来自数学和工程的方法、计算机科学独有的方法两大类。","children":[],"note":""},{"title":"计算思维应用于计算物理学、计算化学、计算生物学、计算经济学和计算机赋能教育。","children":[],"note":""},{"title":"实验范式、理论范式、仿真范式和数据密集型科学发现的详细解释均为浅灰内容，只作了解。","children":[],"note":""},{"title":"有限性、确定性、机械性，以及“基础技能、面向所有人”等浅灰说明只作了解。","children":[],"note":""},{"title":"约简、递归、并行、抽象分解、关注分离、冗余容错、启发式推理和时空折中等七类方法的展开说明只作了解。","children":[],"note":""}],"note":""},{"title":"10 计算机文化","children":[{"title":"文化的广义、狭义概念及广泛性、传递性、教育性、深刻性均为普通或浅灰文字，只作了解。","children":[],"note":""},{"title":"数字时代、数字文化、数字世界、四次工业革命和数字中国的全部内容只作了解。","children":[],"note":""},{"title":"计算机文化的早期观点、现代定义、计算机能力和计算机文化教育的内容只作了解。","children":[],"note":""}],"note":""}],"note":""}],"note":"理解工作原理 → 会算进制和单位 → 区分编码、硬件与软件"}];
